programs.sol:
"""A partial approximation of a French spelling response.

Selected i/u-ending fragments inside words and short u-forms in French
context get positive values. The -enu family after t/v gets a larger positive
value without requiring the language cue. E-final syllables, consonant clusters,
and p/t after é-, dé-, or ré- get negative values. Dictionary frequencies suppress
lookalikes in other languages. Other lexical responses and exact contextual
magnitudes are not modeled.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


def agreement_forms(stems):
    """Append the usual French feminine/plural spelling endings."""
    return frozenset(stem + ending for stem in stems
                     for ending in ('', 'e', 's', 'es'))


I_ENDINGS = agreement_forms(('i', 'ri')) | frozenset(('ir', 'rir', 'cir'))
U_ENDINGS = agreement_forms(('u',))
ENU_ENDINGS = agreement_forms(('enu',))
# Participle fragments from unir, sentir, and suivre.
OTHER_PARTICIPLES = agreement_forms(('uni', 'enti', 'ivi'))
FEMININE_PARTICIPLES = frozenset(stem + ending
    for stem in ('parti', 'sorti') for ending in ('e', 'es'))
# Short participles and the adjective nu ('naked').
SHORT_U_FORMS = agreement_forms(('pu', 'su', 'vu', 'nu'))
FRENCH_PREFIXES = frozenset(('é', 'dé', 'ré'))


@lru_cache(maxsize=50000)
def french_evidence(word):
    if len(word) < 2:
        return 0.0
    frequency = zipf_frequency(word, 'fr')
    other = max(zipf_frequency(word, lang) for lang in ('en', 'es', 'it', 'de'))
    dominance = max(0.0, min(1.0, (frequency - other + 0.5) / 2))
    commonness = max(0.0, min(1.0, (frequency - 2) / 2))
    return dominance * commonness


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0)
    _, word, previous, context = carry
    token = prefix.token_strings[-1]
    within_word = token.isalpha() and bool(previous) and previous[-1].isalpha()
    for piece in re.findall(r'[^\W\d_]+|[^\w]', token):
        if piece.isalpha():
            word += piece
        elif word:
            context = 0.85 * context + 0.15 * french_evidence(word.lower())
            word = ''
    word = word[-50:]
    s = token.strip()
    value = 0.0
    if s.isalpha() and s.islower() and all(ord(ch) < 256 for ch in s):
        gate = max(0.0, min(1.0, (context - 0.1) / 0.2))
        if within_word:
            if s in I_ENDINGS:
                value += 1.25 * gate
            if s in U_ENDINGS:
                value += 1.75 * gate
            if s in ENU_ENDINGS and previous.lower().endswith(('t', 'v')):
                value += 4.5
            if s in OTHER_PARTICIPLES:
                value += 1.5 * gate
        if s in FEMININE_PARTICIPLES:
            value += 1.5 * gate
        if s in SHORT_U_FORMS:
            value += 2.5 * gate
        if token.isalpha() and previous.strip().lower() in FRENCH_PREFIXES:
            if re.fullmatch(r'[bcdfghjklmnpqrstvwxz]e', s):
                value -= 3.3
            if re.fullmatch(r'[bcdfgptv][lr]e?', s):
                value -= 2.0
            if s in ('p', 't'):
                value -= 2.0
    return (doc, word, token, context), value

"""A mainly negative response to Germanic grammatical words, especially determiners.

Track the unfinished word to recognize split spellings and case endings.
Recent function words disambiguate German, Dutch and Scandinavian articles
from identical English/Romance spellings. Most other tokens receive zero.
Matches concern the word so far, not a future word boundary. Split endings
have their own, usually larger, response. A few pronouns,
prepositions, word starters and Hungarian articles are included as well.
"""
import re

READS = ()

EIN_ENDINGS = {'': -1.92, 'e': -4.44, 'en': -5.34,
               'er': -2.74, 'em': -2.59, 'es': -1.72}
POSSESSIVE_ENDINGS = {'': -0.2, 'e': -3.4, 'en': -4.15,
                      'er': -1.1, 'em': -1.2, 'es': -0.3}
DEMONSTRATIVE_ENDINGS = {'e': -1.8, 'en': -2.64, 'er': -0.88,
                         'em': -1.0, 'es': -0.2}
OTHER_GERMANIC = {'een': -3.42, 'geen': -3.7, 'deze': -2.3,
                  'uw': -2.14, 'det': -0.72, 'ett': -1.33,
                  'zur': -1.33, 'zum': -0.95, 'denn': -1.92,
                  'ihn': -1.09, 'sie': -0.5, 'zijn': -1.23,
                  'onze': -0.85, 'nichts': -1.25, 'ingen': -1.87}


def response(word):
    w = word.lower()
    for root in ('ein', 'kein'):
        if w.startswith(root) and w[len(root):] in EIN_ENDINGS:
            value = EIN_ENDINGS[w[len(root):]]
            return value * (1.4 if root == 'kein' else 1.0)
    for root in ('mein', 'dein', 'sein', 'ihr', 'unser', 'euer', 'eur'):
        if w.startswith(root) and w[len(root):] in POSSESSIVE_ENDINGS:
            value = POSSESSIVE_ENDINGS[w[len(root):]]
            return value * (0.82 if root in ('unser', 'euer', 'eur') else 1)
    for root in ('dies', 'jen', 'jed'):
        if w.startswith(root) and w[len(root):] in DEMONSTRATIVE_ENDINGS:
            end = w[len(root):]
            if root == 'jed':
                return {'e': -3.0, 'en': -3.22, 'er': -2.91,
                        'em': -1.7, 'es': -1.2}[end]
            return DEMONSTRATIVE_ENDINGS[end]
    return OTHER_GERMANIC.get(w, 0.0)


# Language groups: Dutch, German, Scandinavian, English, Romance, Hungarian.
LANGUAGE_WORDS = {
    'nl': set((
        'aan als bij dan dat deze die dit door een er geen hebben heeft het hij hun '
        'is je jouw kan maar met naar niet nog om onze ook op te uit uw van voor was '
        'wij worden wordt zij zijn'
    ).split()),
    'de': set((
        'aber als auch auf bei das dass dem den der des die dieser durch ein eine '
        'einem einen einer es für haben hat ihr ihre im ist kann mit nach nicht noch '
        'sich sind und von war werden wir wird zu zum zur über'
    ).split()),
    'sc': set((
        'att av blir den der det du en er ett från för han har ikke inte jeg kan med '
        'men och og om på skal som så til var vi är'
    ).split()),
    'en': set((
        'and are be been being can did do does for from had has have he her his is it '
        'its not of our she that the their these they this those to was we were which '
        'who will with would you your'
    ).split()),
    'rom': set((
        'alla che com con dans del della delle des di du el em en es est et gli il la '
        'las le les lo los mas nel non para per por que qui se si su sua sur sus uma '
        'un una une'
    ).split()),
    'hu': set((
        'az azt csak de egy ez ha hogy is meg mint már még nem vagy van volt és'
    ).split()),
}


def language(words):
    scores = {k: 0.0 for k in LANGUAGE_WORDS}
    for i, w in enumerate(reversed(words[-24:])):
        weight = 0.92 ** i
        for k, vocabulary in LANGUAGE_WORDS.items():
            if w in vocabulary:
                scores[k] += weight
        if 'ij' in w or w.endswith(('lijk', 'heid')):
            scores['nl'] += weight
        if any(c in w for c in 'őű'):
            scores['hu'] += 2 * weight
    best = max(scores, key=scores.get)
    return best if scores[best] > 0.4 else '?'


# Each ambiguous grammatical form has a default and language-specific strengths.
CONTEXT = {
    'de': (0., {'nl': -4.38, 'sc': -2.36, 'de': -1.39}),
    'die': (-2.2, {'nl': -1.35, 'de': -2.53, 'en': -0.38, 'rom': -1.48}),
    'den': (-2.3, {'nl': -4.76, 'sc': -4.23, 'de': -3.85,
                   'en': -0.37, 'rom': -1.0}),
    'der': (-0.6, {'de': -1.13}),
    'dem': (-0.3, {'de': -0.99}),
    'in': (0., {'de': -0.64, 'sc': -0.4}),
    'an': (-0.10, {'de': 0.29}),
    'en': (0.10, {'sc': -1.46, 'nl': -0.2, 'de': -0.23}),
    # German negative/prepositional starters, and Nordic possessives.
    'ne': (0., {'de': -2.48}),
    'ni': (0., {'de': -3.0}),
    'ben': (0., {'de': -2.8}),
    'min': (0., {'sc': -2.8}),
    'din': (0., {'sc': -2.6}),
    'sine': (0., {'sc': -4.4}),
    'dine': (0., {'sc': -4.0}),
    'a': (0., {'hu': -0.54}),
    'az': (0., {'hu': -1.1}),
    'diesel': (0., {'de': -4.3}),  # Beginning of dieselbe/dieselben.
    'da': (0., {'de': 1.1}),
    'mir': (0., {'de': 1.0}),
}


def contextual_response(word, token, words):
    w = word.lower()
    if w in CONTEXT:
        default, strengths = CONTEXT[w]
        value = strengths.get(language(words), default)
    else:
        value = response(word)
    # An ending split off its determiner stem is particularly salient.
    continuation = token.isalpha() and token.lower() != w
    if continuation and value < -0.2:
        ending = token.lower()
        if ending in ('iner', 'inen', 'inem', 'ine', 'ines', 'in'):
            value = {'iner': -5.7, 'inen': -8.0, 'inem': -3.4,
                     'ine': -4.6, 'ines': -3.2, 'in': -4.0}[ending]
        elif ending in ('er', 'en', 'em', 'es', 'e', 'ener', 'ene',
                        'res', 'ure', 'uren'):
            value = -4.3 if ending not in ('res', 'em', 'es') else -2.6
    if w == 'ders' and token.lower() == 'ers':
        value = -3.56  # Beginning of der-selbe / der-selben.
    if continuation and w in ('einf', 'eing'):
        value = -2.8
    if w == 'eyn':
        value = -3.9  # Historical spelling of ein.
    if word.isupper() and len(word) > 1:
        value *= 0.2
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, words = '', ()
    else:
        _, word, words = carry
    token = prefix.token_strings[-1]
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if part.isalpha():
            word = (word + part)[-40:]
        else:
            if word:
                words = (words + (word.lower(),))[-24:]
            word = ''
    value = contextual_response(word, token, words) if word else 0.0
    return (doc, word, words), value

"""Model a content-dependent first-token pulse, usually strongly negative.

Script, spacing, punctuation and English function-word classes set its size.
An unchanged run of the initial token retains the pulse. Otherwise values
are near zero, with brief positive responses to punctuation, quoted line
endings, Markdown fences, line breaks and words just after punctuation.
Dot-prefixed Git metadata and empty starred comment lines also get positive
background responses. Fine token-specific amplitudes are deliberately omitted.
"""
import math
import regex

INDEFINITE_ARTICLES = {'a', 'an'}
PREPOSITIONS = set("""
    about above across after against along among around at before behind below
    beneath beside between beyond by despite down during except for from in
    inside into near of off on onto out outside over past since through
    throughout toward towards under underneath until up upon via with within
    without
""".split())
COPULA = set('be am is are was were been being'.split())
CONJUNCTIONS = set("""
    and or but nor so yet although as because if once since than that though
    unless until when whenever where whereas whether while
""".split())


def start_value(text, raw):
    word = text.strip()
    if word == '<|im_start|>':
        return -14.1
    if word == '<|endoftext|>':
        return 0.72
    if word.startswith('<|'):
        return -9.48
    if not word:
        if '\n' in text:
            return 1.46
        if text == ' ':
            return 1.19
        if text == '  ':
            return -0.65
        return -2.78
    if word and not word.strip('_'):
        return -10.2 if text.startswith(' ') else -5.8
    if len(word) >= 2 and not word.strip('$'):
        return 2.64  # Opening/closing display-math delimiter.
    if word.isdecimal():
        return -0.99
    if regex.search(r'\p{Script=Han}', word) or (raw and 0xe4 <= raw[0] <= 0xe9):
        return -6.45
    if any(c.isalpha() for c in word):
        if not word[0].isalpha():
            return -8.06
        if not word.isascii():
            return -8.64
        lower = word.lower()
        if lower == 'the':
            return -11.11 if text.startswith(' ') else -8.56
        if lower in INDEFINITE_ARTICLES:
            return -13.05 if text.startswith(' ') else -10.6
        if lower == 'to':
            return -13.75
        if lower in PREPOSITIONS:
            return -7.44
        if lower in COPULA:
            return -6.88
        if lower in CONJUNCTIONS:
            return -6.44
        if len(word) == 1:
            return -7.66
        if text.startswith(' '):
            return -10.4
        return -9.26
    if word.startswith('.'):
        return 2.77 if "\n" in text else 0.22
    if word.startswith(','):
        return -0.81
    if word[0] in '([{':
        return -2.69
    if word[0] in ')]}':
        return -0.65
    if word[0] in '\"\'“”‘’`':
        return -3.74
    if word[0] == '#':
        return -4.23
    return -2.27


def punctuation_kind(text):
    word = text.strip()
    if word.startswith('```'):
        return 'fence'
    if ('\n' in text and word[:1] in ('"', "'")
            and not any(c.isalnum() for c in word)):
        return 'period'  # A quoted string ending a line.
    if word.startswith('.') and not any(c.isalpha() for c in word):
        return 'period'
    if word == ',':
        return 'comma'
    if word and word[0] in ')]};' and not any(c.isalnum() for c in word):
        return 'closing'
    if not word and '\n' in text:
        return 'newline'
    return ''


READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    punctuation = punctuation_kind(text)
    if carry is None or carry[0] != document:
        age = 0
        first_token = token
        initial = start_value(text, prefix.token_bytes[-1])
        unchanged = True
        previous = ''
    else:
        _, age, first_token, initial, unchanged, previous = carry
        age += 1
        unchanged = unchanged and token == first_token

    word = text.strip()
    if unchanged:
        value = initial
    elif word.startswith('.git'):
        value = 0.97 if word.startswith('.github') else 0.71
    elif word == '*' and '\n' in text:
        value = 0.77  # Empty starred line in a comment block.
    elif punctuation == 'fence':
        value = 0.9 * math.exp(-age / 10)
    elif punctuation == 'period':
        value = 0.013 + 1.3 * math.exp(-age / 12)
    elif punctuation == 'comma':
        value = 1.21 * math.exp(-age / 3)
    elif punctuation == 'closing':
        value = 1.36 * math.exp(-age / 4)
    elif punctuation == 'newline':
        value = 0.35 * math.exp(-age / 10)
    elif previous in ('period', 'comma', 'closing') and text.strip()[:1].isalpha():
        value = 0.3 * math.exp(-age / 10)
    else:
        value = 0.0
    return (document, age, first_token, initial, unchanged, punctuation), value

programs.haiku:
"""Layer 1 MLP down_proj, component 1094: a document-start detector.

It is nearly silent everywhere except on the first token of a document (a token right
after a document boundary, or the first token of a row). There its activation depends on
what kind of token opens the text:

- a word, name or chat tag (letter-initial token, or "<...>" such as <|im_start|>) pushes
  strongly negative, about -9: a fresh start of text;
- code or markup punctuation and symbols (#, (, =, ", //) push moderately negative, about -4;
- sentence-closing punctuation (. , : ) ; 。) is close to 0;
- digits are slightly negative, about -1;
- a newline is positive, about +2, a single space about +1, and other whitespace about -2.5.

Every later token gives 0.
"""
import unicodedata

READS = ()

WORD_START = -9.0
CODE_PUNCT = -4.0
CLOSING_PUNCT = -0.5
DIGIT_START = -1.0
NEWLINE_START = 2.0
SPACE_START = 1.0
OTHER_WHITESPACE = -2.5
CLOSING = set(".,:;)]}。，！？!?")


def _start_value(token):
    if token.strip() == "":
        if "\n" in token:
            return NEWLINE_START
        return SPACE_START if token == " " else OTHER_WHITESPACE
    text = token.strip()
    first = text[0]
    if first == "<":
        return WORD_START
    if text.isdigit():
        return DIGIT_START
    category = unicodedata.category(first)
    if category.startswith("L"):
        return WORD_START
    if category.startswith("N"):
        return DIGIT_START
    if first in CLOSING:
        return CLOSING_PUNCT
    return CODE_PUNCT


def step(carry, prefix, upstream):
    first_of_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not first_of_document:
        return carry, 0.0
    return carry, float(_start_value(prefix.token_strings[-1]))

programs.sol:
"""A sparse spelling-based approximation, chiefly for mathematical implication.

Unicode implication/therefore signs and selected LaTeX commands are negative;
ordinary arrows are weaker.  Logical connectives have small lexical responses.
There is also an initial-token offset and explicit opening Title:, To and empty
line-comment effects.  A short byte suffix handles split symbols and commands.
This does not model the irregular multilingual spikes or most lexical background.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', 'ignore').strip()
    word = token.lower()
    before = tail.decode('utf-8', 'ignore')
    opening = not before or before.endswith('<|endoftext|>')
    latex = before.rstrip().endswith('\\')
    symbol = token
    if not token and raw[-1:] in (b'\x92', b'\xb4'):
        symbol = (tail + raw).decode('utf-8', 'ignore')[-1:]
    value = -0.08 if opening else -0.002
    if opening and token.isascii():
        if len(token) == 1 and token.isalpha():
            value = -0.31
        elif token.isdigit():
            value = -0.25
    if symbol == '∴':
        value = -4.35
    elif symbol in ('⇒', '⟹'):
        value = -1.45 if raw.startswith(b' ') else -1.0
    elif token == '=>':
        recent = before[-48:]
        formula = (before[-1:].isdigit()
                   and any(c in recent for c in '=+^−')
                   and not any(c in recent for c in "'\";{}[]"))
        value = -1.0 if formula or not raw.startswith(b' ') else 0.02
    elif token == '==>':
        value = -0.4
    elif symbol in ('→', '⟶'):
        value = -0.14
    elif token == '··' and (opening or before.endswith('··')):
        value = -0.73
    elif latex and token in ('Rightarrow', 'Longrightarrow'):
        value = -1.8 if token == 'Rightarrow' else -1.5
    elif latex and token == 'impl':
        value = -1.0
    elif token == 'ies' and before.endswith('\\impl'):
        value = -3.8
    elif latex and token == 'to':
        value = -0.62 if before.strip() == '\\' else -0.05
    elif latex and token == 'under':
        value = -2.0
    elif token == ':' and (
        before == 'Title' or before.endswith('<|endoftext|>Title')
    ):
        value = 4.65
    elif token == 'Title' and opening:
        value = -0.43
    elif token == 'To' and opening:
        value = 1.39
    elif raw == b'//\n' and opening:
        value = -4.51
    elif word == 'because':
        value = 0.19 if raw[:1].isspace() else 0.28
    elif word in ('else', 'otherwise'):
        value = 0.11
    elif word in ('so', 'therefore', 'since', 'hence'):
        value = 0.04
    elif word == 'then':
        value = -0.05
    return (doc, (tail + raw)[-64:]), value

"""Approximate prominent local lexical responses, not a unified topic feature.

Negative estimates cover English immediacy/escape and backward expressions,
and Chinese repetition, reversal, opening/crossing and ongoing-action endings.
A small dictionary-gloss heuristic strengthens selected motion/effort cases.
Positive estimates cover anti-/counter- and selected type/photo completions.
Spelling variants, token boundaries and partial UTF-8 characters matter.
Other predictions are zero except document-initial and dot-leader offsets.
"""
from functools import lru_cache
import regex
import cedict
import jmdict
from opencc import OpenCC

READS = ()
_converter = OpenCC('t2s')


@lru_cache(maxsize=16384)
def simplified(text):
    return _converter.convert(text)


@lru_cache(maxsize=4096)
def counter_word(word, original):
    gloss = ' '.join(cedict.glosses(word) + jmdict.glosses(original)).lower()
    return any(x in gloss for x in (
        'anti-', 'antisubmarine', 'counterargument', 'reactionary',
        'by contrast', 'trans-', 'foul',
    ))


@lru_cache(maxsize=4096)
def motion_or_effort(word):
    definitions = cedict.glosses(word)
    if not definitions:
        return False
    first = definitions[0].lower()
    return (first in {'to struggle', 'to withdraw', 'to wind', 'to walk',
                      'to put', 'to overtake; to catch up with'}
            or 'to rob' in definitions)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, age = '', b'', 0
    else:
        _, previous, tail, age = carry
    raw = prefix.token_bytes[-1]
    token = raw.decode('utf-8', errors='replace')
    current = token.strip().lower()
    before = previous.strip().lower()
    value = 0.0

    # At the first token, digits, isolated letters and whitespace lean negative.
    if age == 0:
        if not current or current.isascii() and current.isdigit():
            value = -0.3
        elif current.isascii() and current.isalpha():
            value = -0.3 if len(current) == 1 else -0.07
        if token in {'package', 'import', 'using'}:
            value = 0.75
        elif token.startswith('//'):
            value = 2.9 if '\n' in token else 0.9
        elif token == '#':
            value = 0.5

    # English idioms, distinguished from ordinary spatial uses of away.
    if current in {'away', 'aways'}:
        value = 0.08
        if before == 'right':
            value = -5.1
        elif before == 'straight':
            value = -3.8
        elif before in {'run', 'ran'}:
            value = -2.7
        elif before == 'running':
            value = -1.5
        elif before in {'throw', 'thrown', 'throwing'}:
            value = -0.55
        elif before in {'move', 'moves', 'moving'}:
            value = -0.3
    elif current in {'backward', 'backwards'}:
        value = -0.3
    elif current in {'ward', 'wards'} and before.endswith(('back', 'down')):
        value = -1.6 if before.endswith('back') else -1.2
    elif before.endswith('straight') and current in {
        'up', '-up', 'across', 'forward',
    }:
        value = -1.1

    # Chinese words and split compound completions, spelling normalized.
    if not raw.isascii():
        word, pre = simplified(token), simplified(previous)
        phrase = pre + word
        if word in {'着', '著'}:
            value = -1.0
            if motion_or_effort(pre):
                value = -2.5
            if (pre in {'下', '新', '巾', '前'} or not tail
                    or regex.search(r'[\p{Hiragana}\p{Katakana}]',
                                    tail.decode('utf-8', errors='ignore'))):
                value = -0.12
        # Repetition; then 'serious' and 'orthogonal' after 正.
        if word == '反复':
            value = -3.5
        elif word == '重复':
            value = -0.85
        elif word in {'复', '複'} and pre == '重':
            value = -3.1
        elif pre == '正' and word in {'经', '交'}:
            value = -2.5
        # Spatial reversal versus dictionary-marked anti-/counter- words.
        if pre == '反':
            if word in {'向', '面', '水', '对'}:
