    r'(?:print(?:f|ln)?|fprintf|perror|puts|input|writeln|Write(?:Line)?|'
    r'\blog(?:f|ln)?|\b(?:warn|error|fatal|debug|info)f|panic|abort_|'
    r'(?:console|log(?:ger|ging)?|fmt)\.(?:log|info|debug|error|warn|warning|fatal)'
