"""Digit-run detector: fires on the second digit of a multi-digit number.

Component layers.1.mlp.down_proj:1099 is a number-position feature. Qwen tokenizes
numbers one digit per token, so a number is a run of consecutive digit tokens
("1997" is 1, 9, 9, 7). This program tracks how many digits in a row the current
token ends, within its document, and predicts:

- the second digit of a number (as in the "9" of "19"): about 2.0, or about 1.3
  when the number starts with 0 (as in "05");
- the first and third digits: about 0 (they do not fire);
- the fourth digit: about 0.5;
- the fifth and later digits of a long digit run: about 1.0;
- every token that is not a digit: 0.

Carried state: the length of the current digit run, its leading digit, and the
document label, so a document boundary restarts the count.
"""

READS = ()


def step(carry, prefix, upstream):
    run, lead, doc = carry if carry is not None else (0, "", None)
    ch = prefix.token_strings[-1]
    if prefix.document_ids[-1] != doc:
        run, lead = 0, ""
    doc = prefix.document_ids[-1]
    if len(ch) == 1 and ch.isdecimal():
        run += 1
        if run == 1:
            lead = ch
    else:
        run, lead = 0, ""
    if run == 2:
        value = 1.3 if lead == "0" else 2.0
    elif run == 4:
        value = 0.5
    elif run >= 5:
        value = 1.0
    else:
        value = 0.0
    return (run, lead, doc), float(value)

