READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    current = prefix.token_strings[-1].lower()
    if carry is None or carry[0] != doc:
        return (doc, current, 0.0), 0.12
    _, previous, last_response = carry
    response = 0.0
    if previous.endswith('y'):
        embedded_y = len(previous) > 1 and previous[-2].isalpha()
        if current.startswith('ou'):
            response = -5.0
            # Compounds like layout and suffixes like joyous are weaker.
            if embedded_y and current.startswith('out'):
                response = -0.3
            elif embedded_y and current.startswith('ous'):
                response = -2.0
        elif current.startswith('uri'):
            response = -2.0
        elif current.startswith(('o', 'u')):
            response = -0.7
        elif current[:1].isalpha():
            response = -0.08
        # Opposite-sign spelling families: yoke, yell, yelp, yolk.
        if current.startswith('oke'):
            response = 1.5 if embedded_y else 4.0
        elif current.startswith(('ell', 'elp', 'olk')):
            response = 1.0
        elif current.startswith(("'all", '’all')):
            response = -3.0
    elif previous.endswith('you') and current[:1].isalpha():
        response = -0.7
    elif previous.endswith('ย') and current and current[0] in 'ิีึืุู':
        response = -0.7
    elif previous.endswith('ゆ') and current.startswith('う'):
        response = -1.9
    elif previous.endswith('よ') and current.startswith('ろ'):
        response = -2.8

    value = 0.001 + response
    if current[:1].isalpha() and last_response < -2:
        value += 0.15 * last_response
    if current.strip() == 'you' and previous.strip() == 'of':
        value += 0.55
    return (doc, current, response), value

