@lru_cache(maxsize=150000)
def frequency(word, language):
    return zipf_frequency(word.lower(), language)


@lru_cache(maxsize=100000)
def hidden_boundary(tail, token):
    if not token.isalpha() or not 2 <= len(token) <= 6:
        return 0.0
    plain = ''.join(c for c in ud.normalize('NFD', token.lower())
                    if not ud.combining(c))
    if sum(c in 'aeiouy' for c in plain) > 1:
        return 0.0
