    for language in ('en', 'de'):
        whole = frequency(tail + token, language)
        if whole >= 3.0:
            continue
        for cut in range(1, len(token)):
            word = tail + token[:cut]
            if 3 <= len(word) <= 20:
                known = frequency(word, language)
                best = max(best, min(known - 3, known - whole - 1))
    if best > 3:
        return 0.5
    if best > 1.5:
        return 0.2
    return 0.07 if best > 0.5 else 0.0


