        if prev == "what":
            cue = 3.5
        elif prev in CONDITIONAL_BEFORE or prev == "," or opens_sentence(raw):
            cue = 1.2
    if prev in PLAIN_VERB_BEFORE:
        cue = 0.0 if cue < 3 else cue * 0.1

    # 2. the word after a cue
    value = cue
    if carry and tok in FOLLOW:
        value = max(value, 0.45 * carry)
    if prev == "since" and tok == "the":
        value = max(value, 1.0)
    return cue, float(value)

programs.sol:
"""A document-start response plus English grammatical collocations.

Add a positive baseline at row starts and changes of document. Elsewhere,
'On' is most negative after words for thought or communication. 'Of' has
an especially negative response after increases, decreases and changes.
'To' after wanting, trying or starting is positive instead. Measurements
and representations give a small positive response to 'of'. Other rules
cover temporal/modal words and a few noun/verb ambiguities.
The previous word is assembled across tokens; document boundaries reset it.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
QUANTITY_CHANGES = {
    'change', 'increase', 'decrease', 'rise', 'fall', 'drop', 'decline',
    'reduction', 'growth', 'improvement',
}
DETERMINERS = {
    'a', 'an', 'the', 'this', 'that', 'my', 'your', 'his', 'her', 'our', 'their',
}

@lru_cache(maxsize=12000)
def meaning(word):
    cats = wordnet.categories(word)
    bases = set(wordnet.base_forms(word)) | {word}
    change = bool(bases & QUANTITY_CHANGES)
    volition = bool(bases & {
        'want', 'wish', 'hope', 'seek', 'try', 'attempt', 'start', 'begin',
    })
    representation = wordnet.is_a(word, 'representation')
    measurement = wordnet.is_a(word, 'measurement')
    topic = (wordnet.is_a(word, 'publication')
             or wordnet.is_a(word, 'investigation'))
    return cats, change, volition, representation, measurement, topic


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail = '' if start else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = re.search(r'([A-Za-z]+)[^A-Za-z]*$', tail)
    previous = match.group(1).lower() if match else ''
    value = -0.003

    if word in {'of', 'on', 'about', 'for', 'to', 'in', 'between', 'against'}:
        cats, change, volition, representation, measurement, topic = meaning(previous)
        if word == 'of':
            value = -0.045 + 0.08 * representation + 0.30 * measurement
            if change:
                value = -0.90
            elif volition:
                value = -0.30
            elif 'noun.feeling' in cats:
                value = -0.14
        elif word == 'on':
            value = -0.02
            value -= 0.09 * ('noun.cognition' in cats)
            value -= 0.12 * ('noun.communication' in cats)
            value -= 0.12 * representation
            value -= 0.14 * topic
            value += 0.09 * ('noun.time' in cats or 'noun.quantity' in cats)
        elif word == 'about':
            value = -0.17
            if set(wordnet.base_forms(previous)) & {'think', 'ask', 'worry', 'excite'}:
                value = 0.15
        elif word == 'to':
            value = 0.20 if volition else 0.0
            if previous in {'is', 'was', 'are', 'were', 'be', 'been', 'am'}:
                value = -0.10
        elif word == 'for':
            value = -0.05 if 'noun.cognition' in cats else 0.0
        elif word == 'in':
            value = 0.01
        elif word == 'between':
            value = -0.06
        else:
            value = -0.23
    elif word == 'beginning':
        value = -0.45 if previous in DETERMINERS else 0.30
    elif word == 'learning':
        value = -0.21
    elif word == 'subject':
        value = -0.30 if previous in DETERMINERS else -0.04
    elif word in {'already', 'yet', 'currently', 'might'}:
        value = 0.19
    elif word == 'again':
        value = -0.20

    if start:
        value += 0.33
    return (doc, (tail + token)[-80:]), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:1105, a sparse, mostly-small feature of the MLP output.

What it does, in plain terms:
1. It is strongly positive (about +0.33) on the first token of each document in a packed row,
   where the model's context restarts.
2. Mid-document it is mostly near zero, but on a few prepositions it swings:
   - "of" after a noun of change or variation ("increase of", "change of", "variation of")
     goes strongly negative (about -0.85);
   - "of" after a noun naming a representation or instance ("version of", "aspect of",
     "example of", "measure of") goes mildly positive (about +0.22);
   - "on" / "about" after a noun of discussion or knowledge ("discussion on", "views on",
     "knowledge about") go negative (about -0.5 and -0.3);
   - "to" after a verb of trying or wanting ("trying to", "wanted to") goes positive (+0.25).
3. A few single words carry consistent offsets (e.g. "yet", "yourself" positive;
   "indeed", "against", "regarding", "beginning" negative).

Everything else is predicted as 0. The rules capture the large-magnitude tails; the bulk of the
small fluctuations on ordinary tokens is not modelled.
"""

READS = ()

CHANGE = {" increase", " increases", " decrease", " decreases", " change", " changes", " shift",
          " reduction", " variation", " variations", " improvement", " improvements",
          " difference", " differences", " trend", " trends", " rise", " drop", " growth",
          " decline", " advancement", " beginning"}
TOPIC = {" knowledge", " discussion", " debate", " view", " views", " review", " research",
         " studies", " study", " literature", " opinion", " thoughts", " information", " details",
         " know", " knows", " knew", " learn", " article", " story", " report", " book",
         " questions", " consensus", " interest"}
REPRESENTATION = {" aspect", " aspects", " version", " versions", " example", " examples",
                  " instance", " instances", " measure", " measures", " measurement", " sample",
                  " model", " models", " theory", " theories", " definition", " notion", " sense",
                  " indicator", " indication", " representation", " estimate", " view", " views",
                  " presence", " test", " statement"}
THINK = {" think", " thinking", " thought", " worry", " worried", " worrying", " concerned"}
TRYING = {" attempt", " attempting", " trying", " tried", " wanted", " want", " wants", " seek",
          " sought", " seeking", " wish", " wished"}
WORD_VALUE = {" indeed": -0.48, " against": -0.25, " again": -0.18, " beginning": -0.33,
              " version": -0.22, " regarding": -0.29, " concerning": -0.23, " yet": 0.26,
              " some": 0.12, " already": 0.15, " actually": 0.17, " itself": 0.16,
              " themselves": 0.17, " yourself": 0.25}


def step(carry, prefix, upstream):
    """Predict the component's activation at the newest token from the prefix alone."""
    docs = prefix.document_ids
    if len(docs) == 1 or docs[-1] != docs[-2]:
        return None, 0.33  # first token of a document (or row): the context restarts
    word = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if word == " of":
        if prev in CHANGE:
            return None, -0.85
        if prev in REPRESENTATION:
            return None, 0.22
        return None, -0.06
    if word in (" on", " about"):
        if prev in TOPIC:
            return None, -0.5
        if prev in THINK:
            return None, 0.0
        return None, -0.08 if word == " on" else -0.16
    if word == " to" and prev in TRYING:
        return None, 0.25
    return None, WORD_VALUE.get(word, 0.0)

programs.sol:
"""Approximate a layout and text-continuation feature.

Ordinary tokens predict zero. Spaces, tabs, and standalone comment/quote
leaders depend on the preceding line's word count and code punctuation.
Padding after prose, especially in multiples of four spaces, is strongest.
Repeated leaders after wordy comments are strong too; numbered source
listings are treated separately. Keep only 700 characters of context,
resetting at document boundaries. Coefficients are empirical estimates.
"""
import re

READS = ()


def response(token, tail):
    marker = token.strip()
    whitespace = token.isspace()
    if not whitespace and not (
        marker in ('*', '>', '>>', '>>>')
        or (len(marker) >= 2 and set(marker) == {'/'})
        or (marker and set(marker) == {'#'})
    ):
        return 0.0
    if '\n' in token or '\r' in token:
        return 0.0 if whitespace else 0.17
    text = tail.replace('\\n', '\n').replace('\\r', '\r')
    lines = text.split('\n')
    numbered = bool(re.fullmatch(r'\s*\d+\t\s*', lines[-1]))
    at_start = not lines[-1].strip() or numbered
    if whitespace and token.startswith('\t') and re.fullmatch(
        r'\s*\d+', lines[-1]
    ):
        # A tab separates the printed line number from the code's indentation.
        width = token.count(' ')
        return (0.05 * width - 0.3 + 0.9 * (width % 4 == 0)) if width else 0.0
    line = (lines[-2] if len(lines) > 1 else '') if at_start else lines[-1]
    line = line.rstrip()
    words = len(re.findall(r'[^\W\d_]+', line))
    code_marks = sum(c in '{}[]();=_`' for c in line)
    end = line[-1:] or ' '
    comment = bool(re.match(r'\s*(?:\d+\s+)?(?://|#|\*|>)', line))
    if whitespace:
        spaces = token.count(' ')
        if '\xa0' in token:
            return 0.05
        if tail.endswith(' \n'):
            if words >= 10:
                return 3.52 if spaces % 4 == 0 else 2.32
            if words >= 3 and spaces % 4 == 0:
                return 1.85
            return 0.82
        if at_start:
            if comment:
                return 0.08
            if words >= 9 and end not in '{}[]();=_`':
                if code_marks <= 1:
                    return 2.1 if spaces % 4 == 0 else 1.4
                return 1.4 if spaces % 4 == 0 else 0.65
            if spaces >= 12:
                return 0.52
            if end in '.!?':
                return 1.0
            return 0.16 if spaces and spaces % 4 == 0 else 0.08
        if spaces >= 15 and not any(c.isalpha() for c in line):
            return 0.47
        return 0.33 if token.count('\t') >= 3 else -0.01
    if at_start and comment:
        if marker == '*' and not token.startswith(' '):
            return 0.03
        if words >= 6:
            value = 4.2 if end.isalpha() or end in '.!?' else 2.8
        else:
            value = 2.1 if token.startswith(' ') else 1.5
        if numbered:
            value *= 0.65 if token.startswith(' ') else 0.35
        return value
    if not at_start:
        if marker.startswith('>') and ' >' in line and words >= 9:
            return 0.53
        return 0.07
    if numbered:
        return 0.0
    if marker.startswith('#') and len(marker) > 1:
        return -0.07
    if words >= 8 and code_marks <= 1:
        return 1.2
    return 0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, tail)
    return (doc, (tail + token)[-700:]), value

"""A small detector of escapes, NUL padding, and opening code comments.

NUL bytes are large after letters, smaller after spaces/digits, and largest
at a document's first position. Backslashes following statement punctuation
are stronger than those in mathematical notation or after letters/digits.
There are also positive responses to date commas and opening code comments.
All other text is approximated by zero (0.08 at a document's first token).
A bounded text history supplies context and resets at document boundaries.
"""
import calendar
import re

READS = ()
LATEX = re.compile(
    r'\\(?:frac|sqrt|left|right|begin|end|mathrm|mathbf|text|'
    r'alpha|beta|gamma|delta|theta|lambda|eta|pi|sum|int|'
    r'overline|times|cdot|infty|Large|qquad)\b'
)
DATE = re.compile(
    r'\b\d{1,2} (?:' + '|'.join(calendar.month_abbr[1:]) + r') \d{4}$'
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    prev = recent[-1:]
    first = not recent
    value = 0.08 if first else 0.0

    if '\x00' in s:
        if first:
            value = 6.94
        elif prev.isspace():
            value = 0.5
        elif prev.isalpha():
            value = 2.5
        elif prev.isdigit() or prev in ')]}':
            value = 1.5
        else:
            value = 1.25
    elif first and s.startswith('/*'):
        value = 1.6
    elif first and s.startswith('//'):
        value = 2.4 if '\n' in s else 1.5
    elif first and s.startswith(('"""', "'''")):
        value = 1.2
    elif s == ',' and DATE.search(recent):
        value = 0.63
    elif '\\' in s:
        math = bool(LATEX.search(recent) or re.search(r'\$[^\n$]{0,60}$', recent))
        if s == '\\':
            if first:
                value = 0.0
            elif prev.isdigit() or prev.isspace():
                value = 0.1
            elif prev.isalpha():
                value = 0.06 if math else 0.2
            elif prev in '"\'':
                value = 0.4
            else:
                value = 0.2 if math else 0.6
        elif s.strip() == '\\':
            value = 0.02 if math else (0.34 if prev.isalpha() else 0.1)
        elif s.endswith('\\') and not s.endswith('\\\\'):
            value = 0.04 if math else 0.16
        elif s == '\\n':
            value = 1.28 if first else 0.07
        elif s == '\\t':
            value = 0.02
        elif s.startswith('\\x'):
            value = 0.08
        else:
            value = 0.025
    return (doc, (recent + s)[-240:]), value

"""A detector of label boundaries and dictionary-like constructions.

The largest negative responses close 'instance of' and other unfinished
prepositional labels. Spaced em dashes and arrows distinguish the entity
from its relation label. Other cues are human indefinite pronouns, grammatical
abbreviations, pronunciation marks, and the newline opening a tool response.
Numbers are approximate training means; this is not a token-ID lookup.
"""
import re

READS = ()
PREPOSITIONS = frozenset('''
    to for with by from at in on into onto about against through between
    among within without under over as than
'''.split())

# Columns: after 'instance of', after other 'of', after another preposition.
LABEL_ENDINGS = {
    ',': (-4.38, -1.22, -0.35),
    ':': (-4.34, -1.51, -0.28),
    '|': (-1.40, -0.61, -0.53),
    '—': (-3.90, -3.25, -2.60),
    '->': (-2.50, -2.37, -1.97),
}
# Dictionary grammatical tags and reference abbreviations.
ABBREVIATIONS = frozenset('''
    adj adv pron prep conj intr tr trans intrans pl sing sg cf fut
    imperf gen dat abl acc nom
'''.split())


def response(s, tail, line):
    token = s.strip()
    word = token.lower()
    match = re.search(r'([A-Za-z]+)$', tail)
    previous = match.group(1).lower() if match else ''

    if '\n' in s:
        return -1.07 if tail.endswith('<tool_response>') else 0.002

    if token in LABEL_ENDINGS:
        if previous == 'of':
            instance = bool(re.search(r'\binstance of$', tail, re.I))
            return LABEL_ENDINGS[token][0 if instance else 1]
        if previous in PREPOSITIONS:
            return LABEL_ENDINGS[token][2]

    if token in {'—', '->'}:
        if not s.startswith(' '):
            return -0.10
        relation = token in line
        if token == '—':
            return -1.48 if relation else -0.87
        return -1.36 if relation else -0.66
    if token == '|':
        return -0.10 if s.startswith(' ') and '|' in line else 0.002
    if token == ',':
        return -0.55 if ', instance' in tail else -0.01
    if token == ':':
        if tail == 'Title' or tail.endswith('<|endoftext|>Title'):
            return -6.97
        return -0.09 if ':' in line else 0.002
    if token == ';':
        return -0.20
    if token == '.':
        if re.search(r'\)\s*,\s*n$', tail):
            return -6.0
        if re.search(r'\)\s*,\s*a$', tail):
            return -2.9
        if previous in {'n', 'v'}:
            return -0.26
        if previous in ABBREVIATIONS:
            return -0.48
        return 0.01

    # Punctuation inside a slash-delimited, stressed pronunciation.
    if token in {'ˈ', 'ˌ'}:
        return -1.5
    phonetic = tail.rsplit('/', 1)[-1]
    if '/' in tail[-45:] and not any(ch.isspace() for ch in phonetic):
        if 'ˈ' in phonetic or 'ˌ' in phonetic:
            if token in {'/', '//'}:
                return -2.5
            if token.startswith('('):
                return -1.7
            if token == ')':
                return -0.65

    # A word, rather than a piece inside an identifier or a longer word.
    if word.isalpha() and s and not s[0].isspace():
        if tail and tail[-1].isalpha():
            return 0.002
    if word == 'of' and previous == 'instance':
        return -2.31
    if word in {'someone', 'somebody'}:
        return -1.32 if word == 'someone' else -3.22
    if token in {'n', 'a'} and re.search(r'\)\s*,\s*$', tail):
        return -1.85 if word == 'n' else -0.26
    if token in {'a', 'an', 'the', 'one'}:
        if re.search(r'\bn\.\s*$', tail):
            return -3.6
        if re.search(r'\b(v|adv|adj)\.\s*$', tail):
            return -1.0
    if word == 'having':
        return -0.32
    if word == 'see':
        return -0.63 if token[0].isupper() else -0.07
    if word == 'or':
        if ',' in tail[-2:]:
            return 0.04
        table = any(x in line for x in (' |', ' ->', ' —'))
        return -0.96 if table else -0.14
    if word == 'to':
        if previous == 'means':
            return -1.37
        if token[0].isupper():
            return -0.21
        if tail.endswith(','):
            return -0.29
    if (token == '.e' and previous == 'i') or (
        token == '.g' and previous == 'e'
    ):
        return -0.20
    if word == 'example' and previous == 'for':
        return -0.26
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, line = '', ''
    else:
        _, tail, line = carry
    s = prefix.token_strings[-1]
    value = response(s, tail, line)
    tail = (tail + s)[-120:]
    line = (line + s).rsplit('\n', 1)[-1][-120:]
    return (doc, tail, line), value

"""A spelling-fragment detector, mainly for e|i across token boundaries.

The next letter makes eig/eir/eik negative, and eil/eit/eist positive.
Whole eigen/eig fragments and Greek epsilon-iota have related responses.
Separate lexical triggers include 登, 鸣/鳴, 繰り, selected kana, and Java
package com. UTF-8 fragments are joined before recognizing characters.
Most weak, context-dependent activity is deliberately ignored.
"""
import codecs
from opencc import OpenCC

READS = ()
_simplify = OpenCC('t2s').convert


def latin_ei(s):
    if s.startswith('ig'):
        if s.startswith('ight'):
            return 0.0
        if s.startswith(('igh', 'igel', 'igu')):
            return -1.6
        return -4.2 if s.startswith('ign') else -7.2
    if s in ('ir', 'ird', 'ik'):
        return -3.9
    if s.startswith('ik'):
        return -2.0
    if s == 'ister':
        return 5.1
    if s.startswith('ist'):
        return 1.2
    if s.startswith(('il', 'it')):
        return 0.0 if s.startswith(('ill', 'ith')) else 1.4
    if s.startswith('ier'):
        return 2.1
    if s in ('ia', 'iv'):
        return -2.2
    return -1.8 if s.startswith('ing') else 0.0


def response(previous, token):
    word = token.strip()
    if not word.isascii():
        word = _simplify(word)
    if word.lower() == 'eigen':
        return -7.2
    if word.lower() == 'eig':
        return -4.5
    if previous.lower().endswith('ig') and token.startswith('env'):
        return -4.6 if previous.lower().endswith('eig') else -3.0
    if previous == 'IG' and token == 'EN':
        return -7.8
    if word in ('登', '鸣'):
        return -7.4
    if word == '登记':
        return -4.9
    if previous.endswith('登') and word.startswith('记'):
        return -7.5
    if word == '缲':  # Simplified form of Japanese 繰.
        return -5.0
    if previous.endswith('繰') and token == 'り':
        return -9.0
    if token in ('り', 'み'):
        return -1.65
    if token in ('き', 'ぎ'):
        return -0.7
    if previous.lower().endswith('e') and token:
        if token.startswith('i') or token.isupper():
            return latin_ei(token.lower())
    if previous.lower().endswith(('ει', 'εί')):
        if token.lower() in ('γ', 'κ'):
            return -7.0
        if token == 'α':
            return -2.2
    if previous.lower().endswith('ε') and token in ('ι', 'Ι', 'ί'):
        return -3.3
    if previous == 'package' and token == ' com':
        return 2.8
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous = ''
        decoder = codecs.getincrementaldecoder('utf-8')('replace')
    else:
        _, previous, decoder = carry
    token = decoder.decode(prefix.token_bytes[-1], final=False)
    value = response(previous, token)
    return (document, token, decoder), value

