"""Candidate v5: the 'ei' spelling of 'eigen' split across tokens, Greek 'ει', and a few CJK words."""
READS = ()

EIG_WORD = {"eigen", "eig"}                                   # whole pieces of "eigen"
EIG_TAIL = {"ig": -7.0, "igen": -9.0, "ign": -4.5, "iger": -6.5, "ige": -6.5, "igt": -5.0, "ik": -5.0}
EI_POSITIVE = {"ister": 5.0, "iler": 4.0, "itle": 5.0, "isl": 3.0, "ier": 2.5, "its": 2.0, "it": 1.5, "il": 1.3}
GREEK_I = set("ιίΙ")
OKURI = set("りみ")


def is_kanji(ch):
    return "一" <= ch <= "鿿"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = cur.strip().lower()
    prev_word = prev.strip().lower()
    if word in EIG_WORD:
        return None, -7.0
    if cur in ("登", "鸣"):
        return None, -7.5
    if cur in ("記", "记") and prev.endswith("登"):
        return None, -7.0
    if cur.startswith(" "):
        return None, 0.0
    if prev_word.endswith("eig") and word[:2] == "en":
        return None, -6.0                                     # "eig" + "env"/"en": eigenvector
    if prev[-1:] in ("e", "E"):
        if word in EIG_TAIL:
            return None, EIG_TAIL[word]
        if word in EI_POSITIVE:
            return None, EI_POSITIVE[word]
    if prev[-1:] in ("ε", "Ε") and cur[:1] in GREEK_I:
        return None, -3.0
    if cur in OKURI and is_kanji(prev[-1:]):
        return None, -2.5
    return None, 0.0

programs.sol:
"""Approximate a grammatical-agreement signal, not the gender of entities.

Recognized feminine articles, possessives and endings are positive; clear
masculine forms are negative. Plurals and ambiguous forms get weaker values.
A rough language guess from recent word frequencies resolves homographs
(Portuguese versus English a, Italian versus French le). German case rules
refine der. Other tokens are mostly zero; lexical/contextual detail is omitted.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'de', 'it', 'es', 'pt', 'nl', '?')


@lru_cache(maxsize=20000)
def language_evidence(word):
    if len(word) < 2:
        return (0.0,) * len(LANGUAGES)
    frequencies = [zipf_frequency(word, lang) for lang in LANGUAGES[:-1]]
    # Unknown-language option prevents forcing Polish, Hungarian, or code
    # into one of the seven languages whose articles we disambiguate.
    frequencies.append(3.3)
    best = max(frequencies)
    return tuple(max(-3.0, f - best) for f in frequencies)


# Closed grammatical classes, grouped by their agreement marking.
CLASSES = (
    (4.6, 'la une'),
    (4.1, 'las uma'),
    (3.7, 'una'),
    (5.3, 'della nella nelle sulla'),
    (4.3, 'delle alla dalla dalle'),
    (6.1, 'zur'),
    (5.0, 'eine'),
    (5.7, 'einer'),
    (4.3, 'keine keiner meine meiner seine seiner deiner deine'),
    (3.0, 'ihre ihrer unsere unserer eure eurer'),
    (3.6, 'die'),
    (2.1, 'der'),
    (2.4, 'cette esta estas questa queste'),
    (5.2, 'toute toutes'),
    (3.6, 'tutta tutte toda todas nuestra nuestras '
          'nossa nossas sua suas alguma algumas'),
    (1.7, 'welche diese dieser aux dell nell'),
    (1.0, 'les'),
    (0.55, 'des'),
    (0.9, 'ses'),
    (1.1, 'celle'),
    (0.7, 'l'),
    (-1.4, 'el il du au'),
    (-0.7, 'un del dal los'),
    (-1.8, 'ein zum sein'),
    (-2.4, 'kein ihr diesem'),
    (-0.4, 'dem'),
    (-3.7, 'ce'),
    (-2.1, 'cet este questo esse'),
    (-1.0, 'son mon ton'),
)
VALUES = {w: v for v, words in CLASSES for w in words.split()}
DATIVE_PREPOSITIONS = frozenset(
    'in an auf von mit zu aus bei nach vor unter hinter neben seit über'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, (0.0,) * len(LANGUAGES), '', '')
    _, scores, unfinished, previous = carry
    token = prefix.token_strings[-1]
    if token.startswith('<|'):
        if token == '<|endoftext|>':
            scores, unfinished = (0.0,) * len(LANGUAGES), ''
        return (doc, scores, unfinished, token), 0.0
    # Finish words incrementally; never inspect future tokens.
    for piece in re.findall(r'[^\W\d_]+|[\W\d_]+', token.lower()):
        if piece.isalpha():
            unfinished = (unfinished + piece)[-60:]
        elif unfinished:
            evidence = language_evidence(unfinished)
            scores = tuple(0.9 * s + e for s, e in zip(scores, evidence))
            unfinished = ''
    language = LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]
    word = token.strip().lower().lstrip("'’- ")
    boundary = (not previous or token[:1].isspace()
                or not (previous[-1:].isalnum() or previous.endswith(('\\', '_')))
                or token[:1] in "'’-")
    value = VALUES.get(word, 0.0)
    if boundary:
        if word == 'le':
            value = (5.5 if language == 'it' else
                     -2.6 if language == 'fr' else 0.0)
        elif language == 'pt':
            if word == 'a':
                value = 3.5 if token.strip() == 'A' else 4.0
            elif word in ('as', 'pela', 'pelas', 'à', 'às'):
                value = 4.9
            elif word in ('da', 'das'):
                value = 6.2
            elif word in ('na', 'nas'):
                value = 5.6
            elif word in ('o', 'um'):
                value = -2.6
            elif word == 'os':
                value = -1.8
            elif word in ('do', 'no', 'pelo'):
                value = -1.5
            elif word in ('dos', 'nos', 'pelos'):
                value = -0.5
        if word == 'de':
            value = 1.7 if language == 'nl' else 0.0
        elif word == 'die' and language in ('en', 'nl', '?'):
            value = 0.0
        elif word in ('sa', 'ma', 'ta'):
            value = 4.5 if language == 'fr' else 0.0
        elif word == 'alle':
            value = 5.3 if language == 'it' else 2.2
        if word == 'der':
            preceding = previous.strip().lower()
            if token.strip().startswith('D'):
                value = -0.6  # Sentence-initial masculine nominative.
            elif preceding in DATIVE_PREPOSITIONS:
                value = 3.8  # Dative 'der' is feminine.
            elif preceding in ('ist', 'war', 'wird', 'hat', 'wo'):
                value = -0.5
            elif previous.endswith(','):
                value = 0.3
            elif language != 'de':
                value = 0.0
        if word == 'l' and (language not in ('fr', 'it')
                            or token.strip() != 'l'):
            value = 0.0
        if word == 'ce':
            value = -4.0 if language == 'fr' and token.strip() != 'CE' else 0.0
        if word in ('son', 'mon', 'ton'):
            value = -1.8 if language == 'fr' else 0.0
        if (word in ('un', 'il', 'el', 'del', 'cet')
                and language in ('en', '?')):
            value *= 0.15
        if word == 'la' and token.strip() != 'la':
            value = 3.7
        if word == 'las' and language != 'es':
            value = 1.6
    else:
        value *= 0.1
        if word == 'une' and previous.lower().endswith('auc'):
            value = 4.5
    if word in ('η', 'ή'):
        value = 2.3  # Greek feminine article / nominal ending.
    elif word == 'ο':
        value = -1.0
    elif word == 'ª':
        value = 1.6  # Feminine ordinal indicator.
    # Common Russian feminine and plural adjective endings (also subwords).
    if re.fullmatch(
        r'[а-яё]*' r'(ная|ной|скую|ской|ская|ную|нную|нной)', word
    ):
        value = 1.8
    elif word in (
        'ая', 'ую', 'енной', 'енную', 'ической', 'альной'
    ):
        value = 1.5
    elif word in ('ный', 'ский'):
        value = -1.2
    elif word in ('ные', 'ных', 'ими', 'шие'):
        value = 0.6
    elif word in (
        'свою', 'своей', 'этой', 'каждой', 'одной', 'всю'
    ):
        value = 2.6
    return (doc, scores, unfinished, token), value

programs.haiku:
"""Activation of one MLP unit in layer 1 of Qwen3-1.7B, as a readable rule.

It tracks grammatical gender and number of articles (and a few determiners) in
Romance and German text. It is positive on feminine or plural articles, such as
"la", "las", "une", "una", "della", "delle", "eine", "einer", "die" (German), and
negative on masculine singular articles, such as "il", "el", "o", "un", "ein",
"du", "ce", "del". Some forms are ambiguous across languages, so the rule keeps
a running guess of the current document's language, from common function words
seen so far in that document:
  - "le" is positive in Italian and negative in French;
  - "a", "as", "da", "das" are articles in Portuguese, where they are positive,
    and prepositions elsewhere, where they stay near zero;
  - "die" is positive in German and zero in English (where it is a verb).
"""

READS = ()

FEM = {" la", " las", " une", " una", " eine", " einer", " della", " delle", " nelle",
       " nella", " alle", " alla", " sulla", " dalla", " zur", " die", " sua", " seine",
       " seiner", " toute", " toutes", " tutte", " ihre", " sa", " cette", " LA", " La",
       " Die", " Una", " Une", " Eine", " Alle", "La", "Die"}
MID = {" der", " les", " des", " das", " nas"}
MASC = {" il", " el", " un", " ein", " du", " del", " dal", " zum", " nel", " au",
        " um", " dem", " los", " Il", " El", " Ein", " Un", " questo", " este"}
PT_ART = {" a", " as", " da", " das", " na", " nas", " uma"}
PT_MASC = {" o", " os", " do", " dos", " no", " um"}
MARKERS = {
    "it": {" di", " che", " sono", " della", " delle", " gli", " nel", " per", " questo",
           " anche", " non", " alla", " dei", " degli", " come", " è"},
    "fr": {" est", " les", " des", " que", " qui", " pour", " dans", " pas", " avec",
           " sur", " mais", " du", " aux", " sont", " une", " ce"},
    "pt": {" não", " são", " também", " uma", " você", " pelo", " pela", " muito", " ser",
           " com", " como", " mais"},
    "es": {" por", " pero", " está", " muy", " los", " del", " es", " para"},
    "de": {" und", " ist", " nicht", " mit", " sich", " auch", " von", " für", " werden",
           " den", " dem"},
    "en": {" the", " and", " of", " is", " to", " with", " that", " for", " are", " was"},
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, {lang: 0 for lang in MARKERS})
    counts = dict(carry[1])
    for lang, words in MARKERS.items():
        if word in words:
            counts[lang] += 1
    carry = (doc, counts)
    best = max(counts, key=counts.get)
    lang = best if counts[best] > sorted(counts.values())[-2] else None
    if word in FEM:
        value = 4.2
    elif word in MID:
        value = 1.2
    elif word in MASC:
        value = -1.2
    elif word == " ce":
        value = -3.0
    elif word == " le":
        value = 4.5 if lang == "it" else (-2.5 if lang == "fr" else 0.0)
    elif word == " die":
        value = 3.0 if lang == "de" else 0.0
    elif word in PT_ART and lang == "pt":
        value = 4.0
    elif word in PT_MASC and lang == "pt":
        value = -2.0
    elif word[-2:] in ("ая", "ую", "ная", "ную", "ной") or word[-1:] == "ую":
        value = 1.6
    elif word[-2:] in ("ый", "ный") or word[-2:] == "ий":
        value = -1.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Short d-ending fragments and acronym completions.

A separate d/D is strongest after consonants, especially s, p and c.
Short consonant+d fragments also respond, more when attached to earlier
letters or capitalized acronym text. Ordinary word endings are mostly quiet.
LaTeX dot/ellipsis commands and percent-d format codes have negative scores.
The document-initial metadata label 'Title:' is a separate strong response.
"""
READS = ()


def consonant_group(letter):
    letter = letter.lower()
    for group in ('spc', 'bktfv', 'gmh', 'lr'):
        if letter and letter in group:
            return group
    return ''


def predict(token, previous, position):
    if token == ':' and previous == 'Title' and position == 1:
        return 8.5
    if not token.endswith(('d', 'D', 'Ds')):
        return 0.0
    core = token.strip().lstrip('._,-/"\'(*')
    if core.endswith('Ds'):  # plural acronyms
        core = core[:-1]
    if not core.isascii() or not core.isalpha() or len(core) > 4:
        return 0.0
    last = previous[-1:]
    if len(core) == 1:
        value = 0.16
        if token[:1].isspace():
            return value - 0.03 + 0.27 * previous.endswith('.')
        if token.startswith('.'):
            initial = len(previous.strip(' .')) <= 3 and last.isalpha()
            return value + (1.4 if initial else 0.0)
        if token not in ('d', 'D', 'Ds'):
            return value
        group = consonant_group(last)
        value += {'spc': 3.63, 'bktfv': 1.76,
                  'gmh': 1.23, 'lr': 0.32}.get(group, 0.0)
        if group and core.isupper() and last.isupper():
            value += 1.69 + 1.75 * (last == 'S')
        if last == '\\':
            return -1.4
        if last == '%':
            return -0.62
        return value

    group = consonant_group(core[-2])
    if previous.endswith('\\') and core.lower() in ('cd', 'ld', 'od', 'vd'):
        return -2.8  # starts of LaTeX product, ellipsis and dotted symbols
    if group not in ('spc', 'bktfv', 'gmh'):
        return 0.0
    value = {'s': 1.37, 'p': 1.30, 'c': 0.46}.get(core[-2].lower())
    if value is None:
        value = 0.30 if group == 'bktfv' else 0.05
    value += (1.25 if group == 'spc' else 0.34) * (len(core) - 2)
    attached = (not token[:1].isspace()
                and not token.startswith(('.', '_', '-', '/')))
    if attached and last.isalpha():
        value += 0.85 + 1.23 * last.isupper()
    if core == 'td' and previous.rstrip().endswith(('<', '</')):
        value -= 0.77
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, position)
    return (document, position + 1, token), float(value)

"""A local exclusivity detector: 'the only' is much stronger than adverbial
'only'. Also recognize unique/sole in several languages, and two limiting
constructions ('up to', 'one-to-'). Uniqueness stems can cross token breaks.
Some university/uni- fragments share the signal. This is a lexical
approximation, not an interpretation of the sentence.
"""
import re

READS = ()
POSSESSIVES = {'my', 'his', 'her', 'our', 'their', 'its', 'your'}
PREDICATIVE_CUES = {'is', 'are', 'was', 'were', 'be', 'been', 'not'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, old_word = '', '', ''
    else:
        _, previous, before, old_word = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    p = previous.strip().lower()
    # Retain just the current word, so a split 'un' + 'ico' is recognizable.
    match = re.search(r'[^\W\d_]+$', token, re.UNICODE)
    if match:
        tail = match.group().lower()
        whole = (old_word + tail)[-32:] if match.start() == 0 else tail
    else:
        whole = ''
    value = 0.0
    if word == 'only':
        value = -0.55
        if p == 'the':
            value = -11.4 if previous.strip() == 'The' else -10.2
        elif p in POSSESSIVES:
            value = -9.0 if p == 'your' else -6.7
        elif p in {"'s", '’s'}:
            value = -2.5
        elif p == 'and':
            value = -1.4
        elif p == 'but':
            value = 0.5
        elif p == 'not':
            value = 0.0
    elif word in {'unique', 'uniquely', 'uniqueness'}:
        value = -1.1
        if word == 'uniquely':
            value = -3.3
        elif word == 'uniqueness':
            value = -4.0 if p == 'the' else -1.5
        elif p in PREDICATIVE_CUES:
            value = -4.0
        elif not token.startswith(' '):
            value = -3.0 if token.islower() else -1.9
    elif word.lstrip('._') == 'unique':
        value = -1.8
    elif word in {'único', 'única', 'únicos', 'únicas'}:
        value = -8.5
    elif word in {'seul', 'seule', 'seuls', 'seules'}:
        value = -2.1
    elif word == '唯一':
        value = -9.0
    elif word == '唯':
        value = -4.8
    elif word == 'unlike':
        value = -1.4
    elif word == 'univ':
        value = -1.5
    elif old_word == 'un' and token[:1].isalpha():
        if word.startswith(('iq', 'ic')):
            value = -7.5
        elif word == 'iv':
            value = -2.7
    elif whole.startswith('únic') and old_word.startswith('ú'):
        value = -9.0
    elif whole.startswith('uniqu') and whole != old_word:
        if not old_word.startswith('uniqu'):
            value = -8.5
        elif whole in {'uniquen', 'uniquene', 'uniquenes', 'uniqueness'}:
            value = -min(7.0, 1.5 * len(word))
    elif whole.startswith('единств'):
        value = -9.0 if old_word.startswith('един') else -4.0
    elif word == '일' and p == '유':
        value = -9.0
    elif word == 'to' and p == 'up':
        value = -0.7 if previous.startswith(' ') else -2.6
    elif word == '-to' and p == 'one':
        value = -3.7
    elif p == 'only' and before.strip().lower() == 'the':
        if word == 'thing':
            value = -3.5
        elif word == 'way':
            value = -1.8
    return (doc, token, previous, whole), value

programs.haiku:
"""'Only' and 'sole/unique' words, read word by word (a word split over several tokens is
joined before it is judged).

- "only" right after "the" (or a possessive such as "your" or "his") is strongly negative:
  "the only one" is the clearest case. Other "only" is weakly negative; "not only" is zero.
- English "unique", "uniquely", "uniqueness" are moderately negative.
- The same sense in other languages ("único", "única", "unico", "unica", "uniche", "einzige",
  "единственный", "seule", "唯一") is strongly negative.
Everything else is predicted as 0."""
READS = ()

DETERMINER_VALUE = {"the": -10.0, "your": -9.0, "his": -7.0, "her": -7.0, "its": -6.0, "their": -6.0}
UNIQUE_EN = {"unique", "uniquely", "uniqueness", "uniquement"}
UNIQUE_OTHER = {
    "unico", "unica", "unicos", "unicas", "único", "única", "únicos", "únicas", "unicamente",
    "uniche", "unici", "einzige", "einziger", "einzigen", "seul", "seule", "seuls", "seules",
    "единственный", "единственная", "единственное", "единственной", "единственную", "唯一", "唯",
}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    prev, word = ("", "") if carry is None or new_doc else carry
    if text[:1].isspace():  # a token starting with a space opens a new word
        prev, word = word, ""
    piece = text.strip().lower()
    if piece and piece.isalpha():
        word += piece
    else:
        prev, word = word, ""
    value = 0.0
    if word == "only":
        if prev in DETERMINER_VALUE:
            value = DETERMINER_VALUE[prev]
        elif prev == "not":
            value = 0.0
        else:
            value = -0.5
    elif word in UNIQUE_EN or piece in UNIQUE_EN:
        value = -2.0
    elif word in UNIQUE_OTHER or piece in UNIQUE_OTHER:
        value = -6.0
    return (prev, word), value

programs.sol:
"""Approximate Dutch-context grammar and spelling responses.

Completed words vote for Dutch by corpus frequency relative to English, German,
French and Spanish. In that context, predict signed responses to grammatical
words (especially of, meaning "or"), short affix-like fragments, and vowel or
consonant spellings. A closed ei syllable has a stronger negative response.
Opening title/comment markers and leading carriage returns are separate rules.
Context resets at document changes and end markers. Unlisted patterns give zero;
this deliberately leaves much lexical variation unexplained.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
# Conjunctions, particles, pronouns, prepositions and grammatical verbs.
WORDS = {
    'of': 13.4, 'wel': 4.6, 'te': 3.6, 'tot': 2.7,
    'als': 2.0, 'dat': 2.5, 'wat': 2.2, 'met': 1.9,
    'wij': 3.1, 'om': 1.3, 'aan': 1.1, 'werd': 1.8,
    'worden': 1.5, 'moet': 1.1, 'doen': 1.3, 'en': 1.3,
    'niet': 0.8, 'nog': 0.8, 'naar': 0.6, 'dit': 0.7,
    'het': 0.4, 'voor': 0.2, 'deze': 0.4, 'is': -0.4,
    'al': 2.7, 'zelf': 3.3, 'mee': 2.7, 'af': 5.3,
    'toe': 4.2, 'laat': 3.1, 'laten': 3.5, 'waar': 3.1,
    'u': -1.8, 'van': -0.1, 'bij': 1.0, 'via': 0.0,
}
SPELLING = {
    'uppercase-of': 3.2, 'internal-of': 3.2,
    'ij': 2.1, 'ou': -3.4, 'ei': -2.0,
    'initial-v': -2.2, 'ge-prefix': 1.6, 'be-prefix': -2.0,
    'ver-prefix': -0.9, 'sch-prefix': -2.3, 'ig-suffix': -1.6,
    'vowel-nd': -1.7, 'vowel-ss': -3.5, 'closed-ei': -7.0,
}

@lru_cache(maxsize=16384)
def dutch_vote(word):
    if len(word) < 2 or len(word) > 40:
        return 0.0
    nl = zipf_frequency(word, 'nl')
    other = max(zipf_frequency(word, lang) for lang in ('en', 'de', 'fr', 'es'))
    if max(nl, other) < 3.0:
        return 0.0
    return max(-2.0, min(2.0, nl - other))


def spelling(word, boundary):
    if boundary and word in WORDS:
        return word
    if word == 'of':
        return 'internal-of'
    if len(word) <= 4:
        if word == 'ij':
            return 'ij'
        if word.startswith('ou'):
            return 'ou'
        if 'ei' in word:
            return 'ei'
        if not boundary and word.endswith('nd') and word[:1] in 'aeiou':
            return 'vowel-nd'
        if not boundary and word.endswith('ss') and word[:1] in 'aeiou':
            return 'vowel-ss'
        if word == 'ig':
            return 'ig-suffix'
        if word.startswith('ver'):
            return 'ver-prefix'
        if len(word) <= 3 and word.startswith('v'):
            return 'initial-v'
        if word.startswith('ge') and len(word) <= 3:
            return 'ge-prefix'
        if word == 'be':
            return 'be-prefix'
        if word == 'sch':
            return 'sch-prefix'
    return ''


def features(carry, token, doc):
    if carry is None or carry[0] != doc:
        carry = (doc, 0.0, '', '', 0, True)
    _, evidence, unfinished, previous, position, leading_cr = carry
    if token in ('<|endoftext|>', '<|im_end|>'):
        return (doc, 0.0, '', '', 0, True), 0.0, '', 0.0
    evidence *= 0.98
    for ch in token:
        if ch.isalpha():
            unfinished = (unfinished + ch.lower())[-64:]
        elif unfinished:
            evidence = max(-5.0, min(10.0, evidence + dutch_vote(unfinished)))
            unfinished = ''
    gate = max(0.0, min(1.0, evidence / 4.0))
    word = token.strip().lower()
    boundary = not token[:1].isalpha() or not previous[-1:].isalpha()
    key = spelling(word, boundary)
    # The ei diphthong followed by consonants (as in eind, eis, veilig).
    if 'i' in word and len(word) <= 4 and re.search(
            r'ei[bcdfghjklmnpqrstvwxyz]+$', unfinished):
        key = 'closed-ei'
    if key == 'of' and token.strip().isupper():
        key = 'uppercase-of'
    fixed = 0.0
    if token == '\r' and leading_cr:
        fixed = -7.7
    elif token == ':' and previous == 'Title' and position == 1:
        fixed = -8.45
    elif position == 0 and token in ('//\n', '//', '--'):
        fixed = {'//\n': -7.05, '//': -0.83, '--': -2.4}[token]
    elif word == 'com' and previous.strip() == 'package':
        fixed = -1.1
    carry = (doc, evidence, unfinished, token, position + 1,
             leading_cr and token == '\r')
    return carry, gate, key, fixed


def step(carry, prefix, upstream):
    carry, gate, key, fixed = features(
        carry, prefix.token_strings[-1], prefix.document_ids[-1])
    weight = WORDS.get(key, SPELLING.get(key, 0.0))
    return carry, fixed + gate * weight

"""Approximate a formatting / repeated-i feature.

Paragraph breaks respond positively, especially after long unbroken text.
A fading count of earlier line endings dampens this response. Repeated interpuncts
also respond positively. The negative response looks for i-consonant-i in short
fragments, including across a token boundary. Transliteration extends this rule
to alphabetic and syllabic scripts, but not Han characters. Familiar English
words and long fragments damp the response. Different intervening consonants
have different strengths; ri and chi are particularly strong within a token.
Capital letters strengthen the response. A separate small rule recognizes the
English and Chinese words for Internet. These rules capture large training
effects while leaving most weaker lexical variation unmodeled.
"""
import math
import re
from functools import lru_cache

import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
I_PAIR = re.compile(r'(?=(i([^aeiou\W\d_]{1,3})i))')
INTERNAL = {
    'r': 2.0,
    'ch': 2.4,
    'sh': 1.1,
    'c': 1.1,
}
BOUNDARY = {
    'h': 1.5,
    'r': 1.1,
    'v': 1.0,
    'w': 1.3,
    'x': 0.85,
}


@lru_cache(maxsize=16384)
def spelling(token):
    if regex.search(r'\p{Script=Han}', token):
        return ''
    return anyascii(token).lower()


@lru_cache(maxsize=32768)
def rarity(word, threshold):
    return 1.0 / (1.0 + 10.0 ** (zipf_frequency(word.strip(), 'en') - threshold))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    line_endings = 0.0 if first else carry[2]
    position = 0 if first else carry[3]
    token = prefix.token_strings[-1]
    p, s = spelling(previous), spelling(token)
    value = 0.0
    if token.strip().lower() == 'internet':
        value = -0.65
    elif token.strip() == '互联网':
        value = -3.5
    capitals = any(ch.isupper() for ch in previous + token)

    if token == '··' and (first or previous == token):
        value = 2.02
    newlines = token.count('\n')
    if newlines == 3:
        if token.count('\r') == 3:
            value = 1.0
        elif '.' in token:
            value = 0.94 + 6.6 / (1.0 + 0.5 * line_endings)
        elif ':' in token:
            value = 1.36 + 3.75 / (1.0 + 0.5 * line_endings)
        else:
            value = -0.17 + 2.08 / (1.0 + 0.5 * line_endings)
        value *= math.sqrt(min(1.0, (position + 1) / 8.0))
    elif newlines in (4, 5) and '.' in token:
        value = 0.82 if newlines == 4 else 2.1

    # Only matches involving the current token count. Earlier matches are ignored.
    joined = p[-6:] + s
    cut = len(p[-6:])
    for match in I_PAIR.finditer(joined):
        end = match.start() + len(match[1])
        if end <= cut:
            continue
        center = match[2]
        if match.start() >= cut:
            strength = INTERNAL.get(center, 0.5)
            if center in ('f', 'h', 'q', 'w', 'x', 'y', 'th'):
                strength = 0.0
            extra = len(s.strip()) - len(match[1])
            response = (strength * math.exp(-0.7 * extra) * rarity(s, 3.0)
                        * (1.25 if capitals else 0.83))
        else:
            strength = BOUNDARY.get(center, 0.45)
            if center in ('q', 'th'):
                strength = 0.08
            extra = len(s) - (end - cut)
            length_penalty = max(0, len(p.strip()) - 3)
            response = (strength * math.exp(-0.3 * extra - 0.5 * length_penalty)
                        * rarity(p + s, 3.5) * (1.75 if capitals else 0.83))
        value -= response
    line_endings = (line_endings + (newlines > 0)) * math.exp(-1.0 / 128)
    return (doc, token, line_endings, position + 1), float(value)

programs.haiku:
"""Layer-1 MLP down-projection, component 1117: a paragraph-break detector.

In plain terms: the component is positive on a line break that ends a paragraph, a run of
three or more newlines directly after a punctuation mark. The strongest is after "." (about
3.5), then ":" (about 2.2); after "?", "!" or ")" it is weaker (about 1), after ";", ",",
quotes or a slash weaker still, and after "}" or a tab about zero. A run of newlines with no
mark before it is about 0.5. Its largest values come at the end of a paragraph that is
followed by a new section heading (the last sentence of an abstract, before RESULTS or
Introduction) or a tool call (a line ending in ":" before a tool call). Those values shrink
later in a document; this is not modelled.

A second, degenerate case: when the whole document so far is one token repeated (for
example a long run of "··"), the component sits at a constant value set by that token.

Everywhere else it is near zero. Its small negative values on word fragments such as "i"
and "Internet" are not modelled, nor is its diffuse small variation.
"""

READS = ()

# Typical activation after a break that follows each mark.
BREAK_AFTER = {".": 3.5, ":": 2.2, "?": 1.1, "!": 1.1, ")": 0.9, "]": 0.7, ">": 0.7}
BREAK_WEAK = 0.4  # after ; , " / and similar marks
BREAK_BARE = 0.5  # a break with no mark before it
BREAK_ZERO = 0.0  # after } or a tab or a closing quote
# Constant value for a document made only of one repeated token.
REPEATED = {"··": 2.0, " _": 1.0}
REPEATED_DEFAULT = 0.3


def _split_break(token):
    """(text before the newlines, number of newlines) for a token ending in newlines."""
    core = token.rstrip("\r\n")
    return core, token[len(core):].count("\n")


def _break_value(core):
    mark = core.rstrip()[-1:]
    if not core.strip():
        return BREAK_BARE
    if mark in BREAK_AFTER:
        return BREAK_AFTER[mark]
    if mark in "}\t”’":
        return BREAK_ZERO
    return BREAK_WEAK


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "token": token, "same": True, "n": 1}
    else:
        same = carry["same"] and token == carry["token"]
        carry = {"doc": doc, "token": carry["token"], "same": same, "n": carry["n"] + 1}
    # Whole document so far is one token repeated (at least twice).
    if carry["same"] and carry["n"] >= 2:
        return carry, REPEATED.get(token, REPEATED_DEFAULT)
    core, newlines = _split_break(token)
    if newlines >= 3:
        return carry, _break_value(core)
    return carry, 0.0

programs.sol:
"""Local English possessive-phrase heuristic.

Possessive determiners and apostrophe-s open a phrase for up to eight tokens;
listed function words and punctuation close it early. WordNet noun senses,
plurality and kinship supply word scores, with negative adjustments for
spousal/probability terms and 'own/personal'. A following complement such as
'of' is strongly negative; a nested apostrophe-s is positive. This captures
a contextual possessive signal, not all of its word-specific variation.
"""
from functools import lru_cache
import wordnet

READS = ()

POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
CONTRACTION_SUBJECTS = {
    'it', 'he', 'she', 'that', 'there', 'here', 'what', 'who', 'let', 'how'
}
PREPOSITIONS = {'of', 'for', 'to', 'in', 'with', 'on', 'at', 'by',
                'from', 'between', 'within', 'about'}
STOPS = PREPOSITIONS | {
    'and', 'or', 'is', 'are', 'was', 'were', 'has', 'have', 'had',
    'a', 'an', 'the'
}

@lru_cache(maxsize=8192)
def word_features(raw):
    w = raw.strip().lower()
    if not raw[:1].isspace() or not w.isascii() or not w.isalpha():
        return {}
    pos = wordnet.parts_of_speech(w)
    cats = wordnet.categories(w, 'noun')
    f = {c.removeprefix('noun.'): 1.0 for c in cats}
    f['noun'] = float('noun' in pos)
    f['plural'] = float(any(b != w for b in wordnet.base_forms(w, 'noun')))
    f['person_plural'] = f.get('person', 0) * f['plural']
    f['person_pure'] = f.get('person', 0) * float(pos == {'noun'})
    for kind in ('relative', 'measure', 'spouse', 'probability'):
        f[kind] = float(wordnet.is_a(w, kind))
    f['personal_modifier'] = float(w in {'own', 'personal'})
    return f

# Semantic weights fitted on training rows; no token-identity table.
DIRECT = {
    'bias': 0.064,
    'person_plural': 0.903,
    'personal_modifier': -0.763,
    'person_pure': 0.274,
    'attribute': -0.266,
    'spouse': -0.991,
    'relative': 0.406,
    'probability': -1.044,
    'noun': 0.18,
}
LATER = {
    'bias': 0.02,
    'person_plural': 0.318,
    'relative': 0.571,
    'person_pure': 0.283,
    'plural': 0.091,
    'measure': -0.104,
    'body': 0.099,
}

def phrase_word_score(raw, age):
    f = word_features(raw)
    f = dict(f, bias=1.0)
    weights = DIRECT if age == 1 else LATER
    return sum(v * f.get(k, 0.0) for k, v in weights.items())


def complement(word, age, origin):
    """Complements of a recently possessed noun, rather than generic 'of'."""
    if origin in (1, 2):
        if age < 2:
            return -0.1 if word == 'of' else 0.0
        near = age <= 3
        if word == 'of':
            return (-3.8 if origin == 1 else -2.5) * (1 if near else 0.33)
        if word == 'for':
            return -1.25 if near else -0.35
        if word == 'to':
            return (-0.5 if origin == 1 else -0.8) if near else -0.02
        if word in {'in', 'with'}:
            return -0.25 if near else -0.03
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_doc = carry is None or carry[0] != doc
    if new_doc:
        carry = (doc, 0, 0, '')
    _, age, origin, previous = carry
    raw = prefix.token_strings[-1]
    w = raw.strip().lower()
    starts_word = raw[:1].isspace() or new_doc
    value = -0.03 if raw == ' of' else 0.0
    if age:
        value = phrase_word_score(raw, age)
    if age and w in PREPOSITIONS and raw[:1].isspace():
        value = complement(w, age, origin)
    if w in {"'s", '’s'} and age:
        value = 1.85 if age == 2 else 0.7 if age == 3 else 0.1

    # Open a new phrase, filtering common contractions of apostrophe-s.
    if w in POSSESSIVES and starts_word:
        age, origin = 1, 1
    elif (w in {"'s", '’s'} and previous
          and previous not in CONTRACTION_SUBJECTS):
        age, origin = 1, 2
    elif w in STOPS or any(c in raw for c in ',.;:!?\n') or age >= 8:
        age, origin = 0, 0
    elif age:
        age += 1

    return (doc, age, origin, w), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:1119, a possession detector.

It is active on the words of a possessed noun phrase, such as "his people",
"your customers", "their chances of". Three things happen:

* The noun right after a possessive ("his", "her", "their", "its", "my", "your",
  "our", or a possessive "'s") is pushed up when it names people or a group
  ("students", "customers", "kids", "family"), up less for body parts and
  belongings ("back", "skin", "home", "car"), and down for words like "own",
  "personal", "way", "chances", "role", "position".
* The preposition that follows a possessed noun is pushed down: "of" most
  (their chances *of*, his title *of*), then "for", then "to". The effect fades
  with distance from the possessive (two words back is strongest). After
  "has/have/had" + a determiner + noun, "of" is pushed down a little.

Everything else is predicted as 0. Only the words in front of the current token
are read, inside the same document. Captures about 25% of the variance.
"""

READS = ()

POSSESSIVE_DETERMINERS = {"his", "her", "their", "its", "my", "your", "our"}
POSSESSIVE_ENDINGS = {"'s", "’s"}
# "it's", "that's" and the like are "is", not possessives.
NOT_POSSESSOR = {"it", "that", "he", "she", "there", "what", "who", "here", "where", "let", "this"}
HAVE_WORDS = {"has", "have", "had", "having"}
PEOPLE = {
    "people", "kids", "children", "students", "customers", "clients", "users", "readers",
    "enemies", "friends", "members", "family", "families", "parents", "patients", "critics",
    "competitors", "opponents", "advisers", "siblings", "father", "mother", "son", "daughter",
    "sister", "brother", "team", "child", "kid", "colleagues", "peers", "fans", "neighbors",
    "employees", "babies", "baby", "young", "customers", "partners", "followers", "voters",
}
OWN_LIKE = {"own", "personal", "way", "name", "favorite", "favourite", "opinion", "respective",
    "other", "individual", "chances", "chance", "partner", "position", "role", "plan", "purpose",
    "goal", "interest", "interests", "relationship", "impact", "level", "performance", "confidence",
    "love", "ability", "style", "total", "perspective", "understanding", "success"}
BODY_OR_THINGS = {"body", "hair", "skin", "feet", "foot", "hands", "hand", "fingers", "knees",
    "back", "side", "front", "head", "face", "eyes", "heart", "car", "phone", "home", "house",
    "desk", "pants", "shoes", "money", "food", "property", "birthday", "death", "career", "debut",
    "environment", "music", "dreams", "boss", "doctor", "customer", "native", "fellow"}
# Preposition weights after a possessed noun: (two words after the possessive, three words after).
COMPLEMENT = {"of": (3.5, 1.3), "for": (1.2, 0.7), "to": (0.5, 0.15)}


def _word(prefix, back):
    """The word `back` tokens before the newest one, lower-cased; '' before the document starts."""
    i = len(prefix.token_strings) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i].strip().lower()


def _possessive(prefix, back):
    """Whether the word `back` tokens before the newest is a possessive determiner or 's."""
    word = _word(prefix, back)
    if word in POSSESSIVE_DETERMINERS:
        return True
    return word in POSSESSIVE_ENDINGS and _word(prefix, back + 1) not in NOT_POSSESSOR


def step(carry, prefix, upstream):
    word = _word(prefix, 0)
    value = 0.0
    if _possessive(prefix, 1):
        if word in PEOPLE:
            value = 1.4
        elif word in OWN_LIKE:
            value = -0.6
        elif word in BODY_OR_THINGS:
            value = 1.0
        elif word.isalpha():
            value = 0.2
    elif word in COMPLEMENT:
        near, far = COMPLEMENT[word]
        if _possessive(prefix, 2):
            value = -near
        elif _possessive(prefix, 3):
            value = -far
        elif word == "of" and (_word(prefix, 3) in HAVE_WORDS or _word(prefix, 4) in HAVE_WORDS):
            value = -0.9
        elif word == "of" and _possessive(prefix, 4):
            value = -0.6
        elif word == "of" and _possessive(prefix, 5):
            value = -0.3
    return carry, value

programs.sol:
"""A local negation signal, strongest on English 'not' and French 'ne ... pas'.

English auxiliaries change the strength of 'not'. Contracted, misspelled and
several non-English negations have their own scales. Most other tokens are
near zero. This is a lexical approximation, not a truth evaluator. It keeps
only the preceding 100 characters and resets at document boundaries.
"""
import re

READS = ()

# Auxiliary and scope-setting words, grouped by observed strength.
NOT_AFTER = (
    ("am has had would 'm 'd 've", -3.8),
    ("still probably likely actually obviously certainly usually", -3.5),
    ("is was were will can have 's but though ought", -3.2),
    ("are should might 're", -2.8),
    ("does did may could must so", -2.5),
    ("do shall", -2.0),
)
FRENCH = set(('je tu il elle nous vous ils elles est sont une des du '
              'que qui pour et ce ça le les au aux mais donc votre notre').split())
SWEDISH = set(('jag du han hon vi ni det den och men att är har '
               'kan ska vill som').split())
ENGLISH = set(('i you he she it we they this that the and but to of '
               'is are was').split())
MISSPELLED = set('dont doesnt didnt isnt cant wont aint'.split())
PARTICLES = {
    # German, Dutch, Danish/Norwegian; Vietnamese and Portuguese.
    'nicht': -1.9, 'niet': -3.6, 'ikke': -4.1,
    'không': -1.25, 'não': -0.55,
    # Korean and Chinese; Japanese and the first part of Thai 'ไม่'.
    '안': -1.8, '아니': -1.8, '못': -1.8, '没': -1.25, '沒': -1.25,
    'ない': -0.5, 'ไม': -2.3,
}
CANDIDATES = MISSPELLED | PARTICLES.keys() | {
    'not', '_not', '.not', '/not', "'t", '`t', 'nt', 'ont', 'int',
    'ot', 't', 'cannot', 'pas', 'inte', '่', 'never', 'without',
}


def predict(token, history):
    raw = token.strip()
    s = raw.lower().replace('’', "'")
    if s not in CANDIDATES and '!' not in s:
        return 0.0
    history = re.sub(r"\\[nrt]", " ", history)
    words = re.findall(r"[\w]+|'\w+", history.lower().replace('’', "'"))
    prev = words[-1] if words else ''
    if prev.startswith("'") and prev not in {"'s", "'d", "'ve", "'m", "'re"}:
        prev = prev[1:]
    context = set(words[-18:])
    if s == 'not' or s in {'_not', '.not', '/not'}:
        if not history:
            return 1.0
        if s != 'not':
            return -1.5
        if history[-1:] in ',)':
            return -1.1
        if prev == 'or':
            return -0.45
        auxiliary = prev
        inverted = prev in {'i', 'you', 'he', 'she', 'it', 'we', 'they'}
        if inverted and len(words) > 1:
            auxiliary = words[-2]
        for auxiliaries, strength in NOT_AFTER:
            if auxiliary in auxiliaries.split():
                return strength - (1.0 if inverted else 0.0)
        return -1.8 if raw[:1].isupper() else -1.65
    if s in {"'t", '`t'}:
        if not history:
            return -0.75
        if prev in {'couldn', 'shouldn'}:
            return -1.0
        if prev in {'can', 'won', 'wouldn'}:
            return -1.55
        if raw == "'T" and history[-3:].isupper():
            return -4.8
        if prev in {'ain', 'n'}:
            return -3.8
        if prev in {'haven', 'hadn'}:
            return -2.5
        return -1.85
    # Negations missing their apostrophe, including split spellings.
    ending = re.search(r"[a-zA-Z]+$", history + token)
    whole_word = ending[0].lower() if ending else ''
    if s in {'nt', 'ont', 'int', 'ot'}:
        if whole_word in MISSPELLED | {'couldnt', 'shouldnt', 'not'}:
            return -8.7 if s == 'nt' else -4.8
    if s == 't' and re.search(
        r"\b(?:don|doesn|didn|isn|aren|wasn|weren|haven|hasn|hadn|"
        r"won|wouldn|couldn|shouldn|can|ain)[ `\\']*$", history, re.I
    ):
        return -3.8
    if s in MISSPELLED:
        if whole_word != s:
            return 0.0
        if s == 'dont' and (
            len(context & (FRENCH | {'de', 'la', 'un', 'en', 'plus'}))
            > len(context & ENGLISH)
        ):
            return -0.1
        return -1.8 if s == 'cant' else -4.0
    if s == 'cannot':
        return -0.7
    if raw == 'pas':
        if re.search(r"\b(?:ne\b|n['’])", history[-80:], re.I):
            return -8.9
        return -5.5 if len(context & FRENCH) >= 2 else -0.5
    if raw == 'PAS':
        return -1.15
    if s == 'inte':
        if not token[:1].isspace() and history[-1:].isalpha():
            return 0.0
        return -7.3 if context & SWEDISH else -0.45
    if s in PARTICLES:
        return PARTICLES[s]
    if s == '่' and history.endswith('ไม'):
        return -4.4
    # A spaced or parenthesized logical NOT, not an exclamation mark.
    if s.lstrip('(').rstrip('$') == '!':
        if s.startswith('(') or token[:1].isspace():
            return -0.55
    if s in {'never', 'without'}:
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, history)
    return (doc, (history + token)[-100:]), value

programs.haiku:
"""Layer 1, MLP down-projection, component 1121: the nominalising suffix of formal Chinese.

The component goes negative on the last character of a formal abstract word built with one
of a few productive suffixes:
  化  (-ize / -ization):   现代化, 自动化, 制度化, 科学化
  性  (-ity / -ness):      针对性, 积极性, 可能性, 一致性
  感  (sense of):          责任感, 使命感, 安全感
  主义 (-ism):             社会主义, 资本主义
It is strongest when the suffix closes a whole word (a multi-character stem such as 制度 or
科学), and weaker when the suffix stands after one character. It is near zero where the
character is part of a fixed noun or verb (文化, 变化, 优化, 女性, 男性, 属性, 个性, 性感),
and everywhere else.
"""

READS = ()

# Typical activation when the suffix is the last token of a whole word, e.g. 现代化 (-3.4).
SUFFIX_WEIGHT = {"化": -2.5, "主义": -2.0, "性": -1.5, "感": -1.8}

# A suffix standing after a single character (e.g. 感化) is weaker.
AFTER_ONE_CHARACTER = 0.3

# Fixed words where the suffix character is part of the root, not a productive suffix.
FIXED_WORDS = set(
    "文化 变化 優化 优化 绿化 變化 强化 消化 美化 深化 转化 氧化 进化 老化 催化 简化 细化 分化 "
    "淡化 净化 硬化 化工 化学 女性 男性 异性 属性 个性 特性 人性 理性 慢性 活性 阳性 "
    "性感 敏感 感性 柔性 韧性 弹性 中性 情感 流感 口感 好感 手感 灵感 质感 美感".split()
)


def is_chinese(text):
    return len(text) > 0 and all("一" <= ch <= "鿿" for ch in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if token in FIXED_WORDS:
        return None, 0.0
    for suffix, weight in SUFFIX_WEIGHT.items():
        if token == suffix:
            # Standalone suffix: full weight after a multi-character Chinese word, weaker otherwise.
            if is_chinese(before) and len(before) > 1:
                return None, float(weight)
            return None, float(weight * AFTER_ONE_CHARACTER)
        if token.endswith(suffix) and len(token) > len(suffix):
            # A whole word ending in the suffix, e.g. 现代化, 针对性.
            return None, float(weight)
    return None, 0.0

programs.sol:
"""A sparse word-form detector centered on "human".

Predict negative responses for human/humans, humanity, Romance cognates,
Chinese/Japanese/Korean human vocabulary, and the misspelling "Huamn".
Split hum/uman and Herman/Roman-like endings have their own response sizes.
Other tokens predict zero: weaker unrelated responses and most contextual
variation are deliberately omitted. Keep only the current word as state.
"""
import re

READS = ()


def response(previous, token):
    s = token.strip().lower()
    if s.lstrip('-') == 'human':
        return -6.43 if token[0].isspace() else -7.16
    if s == 'humans':
        return -4.33
    if s in {'humanity', 'humano', 'mankind'}:
        return {'humanity': -2.47, 'humano': -3.59, 'mankind': -1.39}[s]
    if s == 'hum':
        return -1.0
    text = previous + token
    if text.endswith(('人类', '人類')):
        return -5.75
    if previous.endswith('人') and token.startswith('間'):
        return -3.75
    if text.endswith('인류'):
        return -6.3
    if text.endswith('인간'):
        return -1.5
    # Below: completing one word, rather than beginning the next word.
    if not token or not token[0].isalpha():
        return 0.0
    match = re.search('[^\\W\\d_]+$', text)
    word = match.group().lower() if match else ''
    old = previous.lower()
    if word.endswith('huam') and s == 'am':
        return -1.2
