"""Approximate a local delimiter-reopening signal.

Look back at most twelve tokens, resetting at document boundaries. A quote,
bracket or math delimiter shortly after a matching closer gives a negative
pulse, strongest in comma-separated lists and coordinated expressions. Words
normally give zero. A separate rule handles repeated nonbreaking spaces around
arithmetic operators. Pulse sizes are approximate training-data estimates;
this does not attempt to explain all of the component's smaller activations.
"""
READS = ()

PAIRS = {'"': '"', "'": "'", '`': '`', '$': '$', '(': ')', '[': ']',
         '{': '}', '<': '>', '“': '”', '‘': '’', '«': '»', '‹': '›',
         '「': '」', '『': '』', '《': '》', '〈': '〉', '„': '“',
         '*': '*'}
CONNECTORS = {'and', 'or', 'to', 'nor', 'vs', 'versus', 'y', 'o', 'e',
              'et', 'ou', 'und', 'oder', 'и', 'или', '和', '或', 'と', '及'}


def describe(s):
    """Find the opening punctuation in a short punctuation-only token."""
    if (not s or s[-1] in '\n\r\t ' or len(s) > 8
            or any(c.isalnum() for c in s)):
        return None
    plain = s.replace('\\', '').strip()
    choices = [(i, c) for i, c in enumerate(plain) if c in PAIRS]
    if not choices:
        return None
    i, mark = choices[-1]
    if mark == '*' and s != ' **':
        return None
    # Don't treat a closing quote plus comma/colon as a new quotation.
    if plain[i + 1:] not in ('', '-', '@', '*'):
        return None
