    if s.endswith('\\') and mark not in '$':
        scale *= 0.35
    if mark in '“‘«‹「『《〈„':
        scale *= 1.45
    elif mark == '(':
        scale *= 0.75
    elif mark == '$':
        scale *= 0.64
    elif mark == '`':
        scale *= 0.66
    if not s[0].isspace() and mark in '\"\'':
        scale *= 0.35 if '\\' not in s else 1.0
    if (i and any(c != mark for c in plain[:i])) or plain[i + 1:]:
        scale *= 0.75
    return mark, scale


def pulse(s, history):
    if s == '\xa0':
        for d, prev in enumerate(reversed(history), 1):
            if '\xa0' in prev:
