                    return 0.3
                if d == 2:
                    op = history[-1].strip()
                    if op in {'+', '-', '='}:
                        return -4.8
                    if op in {'×', '/', '÷', '⋅'}:
                        return -3.1
                    if op == '*':
                        return -1.35
                return -0.35
