    desc = describe(s)
    if desc is None:
        return 0.0
    mark, scale = desc
    close = PAIRS[mark]
    core = s.strip().replace('\\', '')
    # Closing and reopening can also be merged into a single token.
    if core == close + ',' + mark:
        return -1.5 if mark in '"\'`' else -0.6
    if mark != close and core == close + mark:
        return -0.45
