                    strength = 4.0
            elif tail == ':':
                strength = 1.8
            elif '\n' in tail:
                strength = 2.5
            elif not tail:
                if mark == '{':
                    strength = 0.7
                elif mark == '`':
                    strength = 1.6 if prev.startswith(' ') else 2.8
                elif mark == '(':
                    strength = 0.9
                elif mark == '[':
                    strength = 3.4
                else:
                    strength = 5.0
                if before.endswith(('.', '?', '!', '。', '？', '！')):
