                strength = 2.4
            else:
                strength = 0.8
        elif d == 2:
            between = history[-1].strip().lower()
            if between in CONNECTORS:
                strength = (2.0 if ',' in tail
                            else 5.5 if mark in '"*' else 4.0)
                if mark == '$':
                    strength *= 0.75
                elif mark == '(':
                    strength = 3.0
            elif not between:
                strength = 2.0
            elif not any(c.isalnum() for c in between):
                strength = 4.0 if between in {'|', '&', '{', '['} else 1.5
            else:
                strength = 0.15
        elif tail == ':' and history[-1].strip() == ',':
            strength = 2.8
        elif d <= 4:
            strength = 0.35
        else:
            strength = 0.0
        if d == 1 and prev.startswith(' ') and mark in '"\'':
            strength *= 0.5
        return -scale * strength
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else []
    s = prefix.token_strings[-1]
    value = pulse(s, history)
    return (doc, (history + [s])[-12:]), float(value)

