    'des': {'un', 'une', 'quelquesunes'},
    'dei': {'uno', 'una'},
    'der': {'einer', 'eine', 'eines', 'einem', 'eins', 'keiner'},
    'из': {'один', 'одна', 'одной', 'одним', 'одном', 'одного', 'каждый'},
