"""Candidate 7: a partitive "of" (one of, some of, which of, all of ...), "such" and the word
right after "such", plus a small negative offset on the first token of each document.

Fires on the word "of" when it follows a quantity or selection word: "one of", "two of",
"some of", "many of", "which of" (strong, about 1.6); "all of", "most of", "more of" (weaker,
about 0.9). Also fires on "such" (about 0.6) and on the article after it ("such a", about 0.9).
Everywhere else it is near zero, with a slight negative value at the first token of a document."""

READS = ()

STRONG = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
          "several", "some", "many", "each", "both", "either", "neither", "none", "any", "which", "whom"}
WEAK = {"all", "most", "more", "much", "few"}

def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.15
    prev = prefix.token_strings[-2]
    if prev in (" such", " Such") and cur in (" a", " an"):
        return None, 0.9
    if cur in (" such", " Such"):
        return None, 0.6
    if cur == " of":
        word = prev.strip().lower()
        if word in STRONG:
            return None, 1.6
        if word in WEAK:
            return None, 0.9
    return None, 0.0

