                value -= 0.5
        elif previous and not previous.strip(' \t'):
            value = 0.7
    elif '\xa0' in token:
        markup = '`' in recent or gutter
        follows_run = previous and not previous.strip('\xa0')
        if token.strip('\xa0') == '':
            if len(token) >= 3 and markup:
                value = 1.9 if follows_run else 1.5
            elif len(token) == 1:
                if gutter or markup and (previous == ' ' or
                                         follows_run and len(previous) >= 3):
                    value = 1.0
                elif follows_run:
                    value = -0.2
    else:
        n = len(token)
        escaped = recent.endswith('\\n') and not recent.endswith('\\\\n')
        if n == 1:
            value = 0.4 if escaped else 0.0
        elif gutter and n >= 3:
            value = (0.25 + 0.55 * math.log(n) if ':' in line
                     else 1.7 + 0.1 * math.log1p(n))
        elif DIAGNOSTIC.fullmatch(line):
            value = 1.0
        elif escaped:
            value = min(2.1, 0.65 + 0.4 * math.log(n))
            if previous == '\\n' and n >= 16:
                value = 0.65
        elif n >= 2:
            if line.strip() in ('//', '#', '+', '-', '*', "'", '"'):
                value = 1.0
            else:
