READS = ()
LETTERS = r'[A-Za-zА-Яа-яЁё]+'
QUALITY_CUES = {
    'be', 'being', 'is', 'are', 'was', 'were', 'very', 'so', 'too',
    'your', 'their', 'his', 'her', 'our', 'my', 'and', 'extremely',
