def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = (old + token).replace('\\n', '\n').replace('\\t', '\t')[-80:]
    before = re.search(LETTERS + r'$', old)
    joined = before is not None and token[:1].isalpha()
    match = re.search(LETTERS + r'$', text)
    raw_word = match.group() if match else ''
    word = raw_word.lower()
    earlier = re.findall(LETTERS, text[:match.start()]) if match else []
    previous = earlier[-1].lower() if earlier else ''
    value = 0.0

    if word in {'honest', 'honesty', 'honestly', 'dishonest'}:
        value = 3.2 if joined else 2.4
    elif word == 'frankly':
        value = 3.4
    elif word in {'humble', 'humbly', 'humbled', 'humbles'}:
        value = 3.8 if joined else 2.2
    elif word == 'humility':
        value = 0.85
    elif word in {'sincere', 'sincerely', 'truthful'}:
        value = 0.7
    elif word in {'kind', 'kindly'}:
        value = 2.5 if previous in QUALITY_CUES else 0.7
        if token.startswith(('.', '_')) or token.isupper():
            value = 0.0
    elif word == 'unkindly':
        value = 3.5 if joined else 1.2
    elif word == 'kindliness':
        value = 5.0 if joined else 0.5
    elif word == 'cleanliness':
        value = 3.0 if joined else 0.4
    elif word == 'kindness':
        value = 0.4
    elif word in {'commitment', 'commitments', 'loyalty'}:
        value = 0.35
    elif word == 'carefully':
        value = 0.55
    elif word == 'clearly':
        value = 0.22

    if token in {'诚', '誠'}:
        value = 5.7
    elif any(ch in token for ch in '诚誠'):
        value = 2.1
    elif token in {'承诺', '承諾', '諾'}:
        value = 2.6
    elif token == '诺':
        value = 0.85
    elif token == '信' and old.endswith(('诚', '誠')):
        value = 2.2
    elif token in {'实地', '實地'} and old.endswith('老'):
        value = 6.0
    return (doc, text), value

"""Short 'for' syllables, with a stronger response at clause openings.

The main case is the English token 'for'.  Capitalization, an opening
conjunction, or a preceding clause separator strengthens it; an ordinary
word governing 'for' weakens it.  Short spelling relatives and split
f/ph + or syllables also fire.  Longer words merely containing 'for'
are not treated as the same fragment. Chinese '对于/對於' is also
recognized, and articles just after 'for' retain a small response.
Unmatched cases return zero. State resets at document boundaries.
"""
import re
from anyascii import anyascii

READS = ()

# Words introducing a clause, assumption, or example.
OPENERS = {'so', 'then', 'but', 'thus', 'hence', 'therefore',
           'however', 'alternatively', 'perhaps', 'suppose'}
EXAMPLES = {'see', 'consider', 'assume'}
SUBORDINATORS = {'that', 'because', 'whereas', 'while'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, '')
    _, previous, last_value, tail = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    word = s.lower()
    latin = anyascii(word)
    prev = previous.strip().lower()
    prev_latin = anyascii(prev)
    match = re.search(r'([A-Za-z]+)$', tail)
    last_word = match.group(1).lower() if match else ''
    value = 0.0

    if word == 'for':
        if s == 'For':
            value = 2.2 if token == s else 2.5
        elif s == 'FOR':
            value = 0.9
        elif '\t' in token:
            value = 0.85
        elif not tail:
            value = 2.3
        elif token == 'for':
            value = 1.2
        elif last_word in SUBORDINATORS:
            value = 4.0
        elif last_word in OPENERS or last_word in EXAMPLES:
            value = 3.5
        elif last_word in {'and', 'or', 'yet'}:
            value = 2.0
        elif previous.isspace():
            value = 1.05
        elif tail.rstrip().endswith((',', ';', ':', '，')):
            before = re.search(r'([A-Za-z]+)[,;:，]$', tail.rstrip())
            opening = before and before.group(1).lower() in OPENERS
            value = 3.8 if opening else 1.6
        elif last_word in {'you', 'him', 'her', 'them', 'us', 'it'}:
            value = -0.15
        else:
            value = 0.27
    # Short for-/fox-like fragments, not arbitrary longer for-words.
    elif re.fullmatch(r'fo(?:r[tdks]|rge|x)s?', latin):
        value = 3.3
        if (latin == 'fort' and token == s and previous
                and previous[-1].isalpha()):
            value += 1.7
    elif latin in {'fore', 'forth', 'forn'}:
        value = 1.7
    elif latin == 'fo' or s == 'フォ':
        value = 1.1 if s.isascii() else 2.3
    elif latin in {'for', 'fur', 'voor'}:
        value = 2.8 if latin in {'for', 'voor'} else 1.0
        if latin == 'fur' and token == s:
            value = 2.2
    elif re.fullmatch(r'[._-]+for', s, re.I):
        value = 0.8
    elif s in {'对于', '對於'}:
        value = 1.2
    elif s in {'于', '於'} and prev in {'对', '對'}:
        value = 5.0

    # A short syllable can begin in the preceding token.
    if token == s and previous:
        if prev_latin.endswith(('f', 'ph')):
            syllable = latin if latin.startswith('or') else word
            if re.fullmatch(r'(?:or[a-z]?|urt?|ör|ør|oe)', syllable):
                value = 4.0
                if prev_latin.endswith('ph'):
                    value = 3.5 if len(prev_latin) <= 3 else 0.5
                elif len(prev_latin) > 3 or prev_latin.endswith(('ff', 'ulf')):
                    value = 1.0
                elif len(prev_latin) == 1 or not prev_latin[-2].isalpha():
                    value = 3.0 if word.startswith('ur') else 7.5
                if word == 'ör':
                    value = 12.0
            elif re.fullmatch('[öüäøó][hr]?', word):
                value = 2.8
            elif s == '.R' and prev_latin.endswith('f'):
                value = 1.5
        elif (anyascii(tail[-6:]).lower().endswith(('fo', 'pho'))
              and re.fullmatch(r'r[a-z]{0,3}', latin)):
            value = 4.5
        if previous == 'フォ' and s.startswith('ー'):
            value = 3.2

    # A little of the response persists on articles immediately after 'for'.
    if prev == 'for' and word in {'a', 'an', 'more'}:
        linger = 1.15 if previous.strip() == 'For' else 0.2 + 0.2 * last_value
        value = max(value, linger)

    return (doc, token, value, (tail + token)[-100:]), float(value)

"""Approximate the component's large response in Hungarian passages.

Relative word frequencies and double-acute vowels establish a language signal.
Within that context, dictionary statistics distinguish word beginnings from
endings and complete words. Word position and the presence of earlier vowels
provide additional adjustments. This is a word-form heuristic, not a token lookup.
"""
from collections import defaultdict
from functools import lru_cache
import re
from wordfreq import top_n_list, zipf_frequency

READS = ()
VOWELS = set('aáeéiíoóöőuúüű')
# Soften corpus frequencies so grammatical words do not dominate the lexicon.
POSITIONS = defaultdict(lambda: [0., 0., 0.])
PREFIXES = defaultdict(float)
WORDS = {}
for word in top_n_list('hu', 30000):
    if not word.isalpha():
        continue
    weight = 10 ** (0.4 * zipf_frequency(word, 'hu'))
    WORDS[word] = weight
    for length in range(1, len(word) + 1):
        PREFIXES[word[:length]] += weight
    for length in range(1, min(6, len(word)) + 1):
        POSITIONS[word[:length]][0] += weight
        POSITIONS[word[-length:]][2] += weight
        for i in range(1, len(word) - length):
            POSITIONS[word[i:i + length]][1] += weight


@lru_cache(maxsize=50000)
def evidence(word):
    if len(word) < 3:
        return 0.
    hu = zipf_frequency(word, 'hu')
    other = max(zipf_frequency(word, lang)
                for lang in ('en', 'de', 'cs', 'sk', 'fi', 'tr', 'ro'))
    if max(hu, other) <= 2.:
        return 0.
    return min(2., max(-1., hu - other))


def completion(word):
    return WORDS.get(word, 0.) / max(1., PREFIXES.get(word, 0.))


@lru_cache(maxsize=50000)
def word_shape(piece, word, starts_word):
    counts = POSITIONS.get(piece, (0., 0., 0.))
    total = max(1., sum(counts))
    beginning, ending = counts[0] / total, counts[2] / total
    prior = word[:-len(piece)]
    before_first_vowel = not any(c in VOWELS for c in prior)
    return (0.5625 - 0.5732 * starts_word
            + 1.6723 * beginning - 0.9567 * ending
            - 0.3216 * completion(piece) - 0.3382 * completion(word)
            + 0.0894 * min(len(piece), 6) / 6.
            - 1.6292 * min(len(prior), 12) / 12.
            + 0.3792 * before_first_vowel)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.)
    _, previous, signal = carry
    match = re.fullmatch(r'(\s*)([^\W\d_]+)', prefix.token_strings[-1].lower())
    if not match:
        if previous:
            signal = max(-2., .85 * signal + evidence(previous)
                         + 2. * any(c in 'őű' for c in previous))
        return (doc, '', signal), 0.
    piece = match[2]
    start = bool(match[1]) or not previous
    if start and previous:
        signal = max(-2., .85 * signal + evidence(previous)
                         + 2. * any(c in 'őű' for c in previous))
    word = piece if start else previous + piece
    confidence = signal + 3. * any(c in 'őű' for c in word)
    gate = min(1., max(0., (confidence - .5) / 2.))
    return (doc, word[-64:], signal), gate * word_shape(piece, word, start)

"""A sparse spelling-and-phrase approximation, not a general topic detector.

Negative cues are theme/topic words in several scripts, Greek theta-e/eta
stems, and split th-e / Cyrillic tez wordpieces. Some split th-i/th-y
spellings have positive cues. 'Of' after a topic noun contrasts with
'of' after thing-words and some quantity expressions. Most tokens receive
zero. Recent bytes reconstruct split characters and wordpieces;
all history resets when the document changes.
"""
import regex as re
from anyascii import anyascii

READS = ()
TOPIC_NOUNS = {'theme', 'themes', 'subject', 'title', 'premise'}
THING_WORDS = {'something', 'nothing', 'anything', 'everything',
               'thing', 'things'}


def activation(old, token, previous):
    s, prev = token.strip(), previous.strip()
    if s == 'of':
        if prev in THING_WORDS:
            return 4.0
        if prev in TOPIC_NOUNS:
            return -1.8
        if prev == 'topic':
            return -0.45
        if prev == 'little':
            return 1.7
        if prev == 'first':
            return 1.0
        if prev == 'term':
            return 0.6
    if s == 'about' and prev in {'what', 'everything', 'something', 'nothing'}:
        return 1.0

    text, cut = old + token, len(old)

    def new(pattern, split=False):
        # Count a spelling only when this token supplies part of it.
        return any(m.end() > cut and (not split or m.start() < cut)
                   for m in re.finditer(pattern, text))

    if s in {'主题', '主題', 'テーマ'}:
        return -2.3
    if s.endswith(('主题', '主題')):
        return -1.2
    if s in {'题', '題'}:
        if text.endswith(('話題', '话题', '課題', '课题', '標題', '标题')):
            return -2.5
        return -0.7
    if new(r'тези', split=True):
        return -1.5
    if new(r'тез', split=True):
        return -3.3
    if new(r'(?<!\p{Script=Cyrillic})темат'):
        return -3.6
    if new(r'(?<!\p{Script=Cyrillic})тем[ауыео]'):
        return -6.8

    # The second consonant of these Greek stems is stronger than the vowel.
    if new(r'θ[εέηή][κσμ]'):
        return -6.0
    if new(r'θ[εέηή][τλ]'):
        return -3.0
    if new(r'θ[εέ]'):
        return -2.7
    if new(r'θ[εέ][ιίς]'):
        return -1.4
    if re.search(r'\p{Script=Greek}', token):
        return 0.0

    if s == 'theme':
        return -0.9 if token[:1].isspace() else -0.5
    if s == 'themes':
        return -1.5
    if s == 'thematic':
        return -2.3
    if s == 'thesis':
        return -0.9 if token[:1].isspace() else 0.0

    if new(r'(?<![a-z])(?:thema|themen|temas?|thèmes?)(?![a-z])'):
        whole = re.search(r'them[ae]|tema|thème', token)
        return -3.5 if whole else -5.5

    # Transliteration also handles accented th-e wordpieces.
    a, b = anyascii(old).lower(), anyascii(token).lower()
    text, cut = a + b, len(a)
    if new(r'(?<![a-z])(?:themat|temat)'):
        return -3.0
    if new(r'bibliote[ck][ai]'):
        return -4.3
    if new(r'bibliote[ck]'):
        return -2.5
    if new(r'the[ckq](?![ou])', split=True):
        return -4.5
    if new(r'theli$', split=True):
        return -2.3
    if new(r'thel$', split=True):
        return -1.2
    if new(r'thes(?:is|es)', split=True):
        return -3.2
    if new(r'the[st]', split=True):
        return -0.9
    if new(r'theme', split=True):
        return -3.8
    if new(r'them', split=True):
        return -0.3
    if new(r'(?<![a-z])th(?:iev|igh|ine|ier|irt)', split=True):
        return 2.5
    if new(r'(?<![a-z])th(?:ey|y|ay|ick)\b', split=True):
        return 2.5
    if new(r'the', split=True):
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '')
    raw = prefix.token_bytes[-1]
    boundary = len(carry[1].decode('utf8', 'replace'))
    joined = (carry[1] + raw).decode('utf8', 'replace').lower()
    old, token = joined[:boundary], joined[boundary:]
    value = activation(old, token, carry[2])
    return (doc, (carry[1] + raw)[-100:], token), value

programs.haiku:
"""Counting words for people and things (negative), with a few small positive verbs.

The component goes negative on the word that opens a counted noun phrase: a classifier
or quantifier such as 个, 名, 位, 项 (or a token ending in one, like 一个, 这个, 一名,
一位, 多位, 第2名) that introduces the thing being counted.
- person counts 名/位 after a number or determiner (一名, 一位, 多位, 第2名, 3名): -2.5;
- item classifiers 个/個/项/颗/枚/辆 and phrases like 一个/这个/每个: about -0.9;
- large-number units 万/亿 after a number: -0.7;
- whole-group words 全体 (-2.2) and 各位 (-1.0); bare 这 (-0.3) and 那 (-0.4);
- the interpunct separator ·· (-0.5);
- action verbs 促, 迎, 抵, 赶, 求, 抢 (+0.6 to +1.5).
Compound nouns that merely end in one of these characters (车辆, 单位, 签名, 定位) are 0,
and every other token is 0. Predicts the activation only from the current token and the
one before it; no state is carried.
"""
READS = ()

COUNTED = set("个個名位项項颗顆枚辆輛万萬亿")
PERSON = set("名位")
LEAD = set("一两二三四五六七八九十百千万亿几多0123456789第每某这那各有了找哪")
ALL_PHRASES = {"全体": -2.2, "各位": -1.0, "这": -0.3, "那": -0.4}
PUSH_VERBS = {"促": 1.0, "迎": 0.8, "抵": 1.0, "赶": 1.5, "求": 0.7, "抢": 0.6}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    if tok in ALL_PHRASES:
        return None, ALL_PHRASES[tok]
    if tok == "··":
        return None, -0.5
    if tok in PUSH_VERBS:
        return None, PUSH_VERBS[tok]
    if not tok or tok[-1] not in COUNTED:
        return None, 0.0
    head = tok[:-1]
    counted = any(ch in LEAD for ch in head) or (prev[-1:] in LEAD)
    if head and not counted:
        return None, 0.0          # a compound noun such as 车辆 or 单位
    if tok[-1] in PERSON:
        return None, -2.5 if counted else -0.4
    if tok[-1] in "万萬亿":
        return None, -0.7
    return None, -0.9

