"""Sparse token-level approximation, chiefly for Chinese network vocabulary.

Netizens and network words give negative values, including continuations across
UTF-8/token boundaries.  The colon after document-initial Title gives +6.46.
Smaller rules cover a Greek vowel fragment, /badge URL paths, social handles,
double middle dots, and document-initial code markers.  Everything else gives
zero.  These rules capture selected strong responses, not general semantics.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, tail, position = '', b'', 0
    else:
        previous, tail, position = carry[1], carry[2], carry[3] + 1
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    word = token.strip()
    combined = tail + raw
