        # Two bytes of a character in the net-radical part of Unicode.
        value = -8.2
    elif raw == b'\x91' and tail.endswith(b'\xe7\xbd'):
        value = -4.9  # the final byte completing 网
    elif raw == b'\xbd' and tail.endswith(b'\xe1'):
        value = -0.73  # incomplete polytonic Greek vowel
    elif word == '网友':
        value = -6.1
    elif word == '網友':
        value = -3.0
    elif word in ('网络', '網路', '網絡', '网上'):
        value = -2.8
        if previous in (
            '社交', '远程', '信息', '神经', '计算机', '无线', '局域', '虚拟'
        ):
            value = -1.0
    elif word in ('网', '網', '网页', '網頁', '网购'):
        value = -1.8
    elif word in ('路', '路上', '络', '絡', '上') and previous.endswith(
        ('网', '網', '网络', '網路')
    ):
        if word in ('络', '絡'):
            value = -1.7
        elif previous.endswith(('网络', '網路')):
            value = -3.0
        else:
            value = -6.0
    elif word in ('购物', '購物') and previous in (
        '线上', '線上', '网上', '網上', '在线'
    ):
        value = -2.4
    elif word == '友':
        value = -0.8
    elif word in ('官网', '官網', '网络传播', 'ネット'):
        value = -0.8
    elif word in ('信息', '來源', '来源', '来源于'):
        value = -0.45
    elif token == ' (@':
        value = -1.2
    elif word == 'adge' and previous == '/b':
        value = 0.95  # a /badge path in a web address
    elif word == '··':
        value = -0.75

    if first:
        if word == 'def':
            value = 2.96
        elif word in ('class', 'export', 'int', 'string'):
            value = 1.25
        elif word in ('package', '<?', '#define', '#ifndef', '#pragma'):
            value = 0.85
        elif token == '//\n':
            value = -3.86
        elif word == '/*':
            value = -0.5

    # Decode a tiny byte suffix to remember characters split across tokens.
    if '\ufffd' in word:
        previous = combined[-12:].decode('utf8', errors='ignore').strip()
    else:
        previous = word
    return (doc, previous, combined[-6:], position), value

"""Surface auxiliaries and finite verb endings in several languages.

The strongest English response is HAVE, raised after personal pronouns.
Romance past/conditional/subjunctive fragments and East Asian polite
predicate endings are positive too. Language estimates reduce accidental matches
inside unrelated words. Unrecognized tokens produce zero; this is not a parser.
Opening-format and dotted-separator patterns have negative responses.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# The language of recent completed words is estimated from counted word
# frequencies. Extra languages prevent forcing an unrelated word into Romance.
LANGS = ('en', 'de', 'fr', 'it', 'es', 'pt', 'tr', 'fa', 'nl', 'sv',
         'da', 'nb', 'fi', 'hu', 'pl', 'cs', 'ro', 'id', 'ms', 'vi')

@lru_cache(maxsize=65536)
def language_evidence(word):
    frequencies = [zipf_frequency(word, lang) for lang in LANGS]
    if max(frequencies) < 3:
        return (0.,) * len(LANGS)
    average = sum(frequencies) / len(LANGS)
    return tuple(f - average for f in frequencies)

# The lexical auxiliary HAVE and close equivalents (including possessive
# tener/ter); ambiguous one-letter forms are handled separately below.
HAVE_FORMS = {
    'de': set('habe hast hat haben habt hatte hatten hätte hätten'.split()),
    'fr': set('avoir avons avez ont'.split()),
    'it': set('avere aver ho hai ha hanno abbiamo avete'.split()),
    'es': set('haber ha han he hemos habéis tener tiene tienen tengo '
              'tenemos tenéis hay'.split()),
    'pt': set('ter tem têm tenho temos tinha tinham haver havia'.split()),
}
ENGLISH = {'have': .23, 'has': .13, 'had': .38, 'having': .15,
           'would': .296, 'could': .22}


def predict(token, prev, history, word, lang, position):
    w, p = token.strip().lower(), prev.strip().lower()
    spaced = token[:1].isspace() or not prev
    # Separate negative responses to opening metadata and decoration.
    if token == ':' and prev == 'Title' and position < 3:
        return -3.66
    if token == '<!' and position == 0:
        return -5.49
    if token and set(token) == {'·'} and len(token) >= 2:
        return -0.86
    if spaced and w in {'avais', 'avait', 'avaient'}:
        return 2.34
    if spaced and w in {'tinha', 'tinham'}:
        return 1.7
    if w in ENGLISH and spaced:
        value = ENGLISH[w]
        if w in {'have', 'has', 'had'}:
            people = {'i', 'we', 'you'} if w == 'have' else {'he', 'she'}
            if w == 'had':
                people |= {'i', 'we', 'you'}
            for distance, prior in enumerate(reversed(history[-3:])):
                if prior.strip().lower() in people:
                    value += (.59 if w != 'has' else .44) * (.55 ** distance)
                    break
            if p == 'they' and w != 'has':
                value += .22
