    if w in {"'ve", '’ve'}:
        return 0.85
    if w in {"'d", '’d'}:
        return .7 if p in {'i', 'you', 'we', 'he', 'she', 'they', 'it'} else .15
    if w == 'got' and p in {"'ve", '’ve', "'s", '’s', 'have', 'has'}:
        return 0.83
    if w in {"'ai", '’ai', "'a", '’a'} and lang == 'fr':
        return 1.24
    if spaced and w == 'ter' and lang == 'pt':
        return .35
    if spaced:
        for language, forms in HAVE_FORMS.items():
