    # French BE/HAVE, and Spanish HAVE. These also occur as standalone pieces.
    if lang == 'it' and re.fullmatch(
            r'(?:foss?|avess?|dovess?|potess?|voless?|stess?)(?:e|i|imo|ero|o)?', word):
        return 2.1
    if lang == 'fr' and re.fullmatch(r'(?:euss|fuss)(?:e|es|ent)?', word):
        return 2.4
    if lang == 'es' and re.fullmatch(r'(?:hubier|hubies)(?:a|an|e|en)?', word):
        return 2.8
