        if word.endswith(('aient', 'oient')) and w.endswith('ient'):
            return 2.1
        if w in {'ait', 'oit', 'oît', 'iez', 'erais', 'rait', 'ât', 'ût'}:
            return 1.76
        if w in {'ais', 'ions'}:
            return 0.63
        if w in {'it', 'ai'} and word.endswith(('ait', 'oit', 'rai')):
            return 1.69
        if w == 'ent' and word.endswith('ssent'):
            return 1.2
    if lang in {'fr', 'it', 'pt', 'es'}:
        if w in {'asse', 'isse', 'esse', 'usse', 'assi', 'essi',
                  'ass', 'iss', 'ess', 'uss'}:
            return 1.0
        if w in {'se', 'i', 'imo', 'ero'} and re.search(r'[aeiou]ss[^s]*$', word):
            return 0.7
    if lang == 'es':
        if w in {'aba', 'abas', 'aban', 'áb', 'ara', 'aran', 'ase',
                  'ieran', 'iera', 'iese', 'asen'}:
            return 1.7 if len(word) > 5 else .2
        if w in {'ía', 'ían', 'aría', 'ría', 'erías', 'iría'}:
            return 1.13
        if w == 'ia' and word == 'habia':
            return 2.4
        if w in {'amos', 'os'} and re.search(r'(?:[áí]|ri[ae])m?os$', word):
            return 1.0
    if lang in {'it', 'pt'}:
        if w in {'v', 'vo', 'va', 'ano', 'am'} and re.search(
                r'(?:av|ev|iv)(?:o|a|ano|am)?$', word):
            return 1.54
        if w in {'ava', 'eva', 'avo', 'evo', 'avano', 'evano', 'aria', 'eria', 'iria'}:
            return 1.38
        if w == 'va' and word.endswith(('ava', 'eva', 'iva')):
            return 1.1
        if w in {'reb', 'rebbe', 'rebbero', 'erebbe', 'irebbe'}:
            return 1.27
        if lang == 'pt' and w in {'ia', 'iam'} and word.endswith(
                ('teria', 'poderia', 'tinha')):
            return 1.3
    if lang == 'tr':
        if w in {'dır', 'dir', 'dur', 'dür', 'tır', 'tir', 'tur', 'tür',
                  'ir', 'ır', 'ur', 'ür', 'iz', 'ız', 'uz', 'üz'}:
            return 0.49
        if w in {'yor', 'orum', 'yorum', 'yoruz', 'tık', 'tik'}:
            return 1.1
    return 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, fragment, scores, position = (), '', [0.] * len(LANGS), 0
    else:
        _, history, fragment, scores, position = carry
    token = prefix.token_strings[-1]
    if token[:1].isspace() and fragment.isalpha() and len(fragment) > 1:
        scores = [s * .9 + e for s, e in
                  zip(scores, language_evidence(fragment))]
    lang = LANGS[max(range(len(scores)), key=scores.__getitem__)]
    if max(scores) < .1:
        lang = 'en'
    # Keep just the unfinished word and three preceding tokens, not a row scan.
    if token[:1].isspace():
        fragment = ''
    fragment += token.lower()
    fragment = re.split(r'[^\w\u200c]', fragment)[-1][-40:]
    prev = history[-1] if history else ''
    value = predict(token, prev, history, fragment, lang, position)
    return (doc, (history + (token,))[-3:], fragment, scores, position + 1), float(value)

