"""Verb auxiliaries and finite-verb endings across languages.

The component marks the verb-form tokens of a clause: the auxiliary 'have' (English
"I have", "we had", "I've got"; French "il a", "avait"; Spanish "ha", "había"; German
"hat", "haben"; Italian "ha", "avevano"), and the tense/mood endings of Romance
imperfect, conditional and subjunctive verbs ("-ait", "-ient", "-aba", "-oit", "-iera").
It also fires on the sentence-final polite endings of Japanese (ます, です) and Korean
(니다). Dot leaders (··) push it negative. Everything else is predicted as 0.
"""
READS = ()

PERSONAL = {" I", "I", " you", "you", " we", "We", " We", "we", " they", "They", " They",
            " he", "He", " He", " she", "She", " She", "You", " You", "’t", "'t"}
NOT_SUBJECT = {" that", " which", " who", " and", " or", ",", ")", " can", " should",
               " people", " studies", " it", " It"}
FRENCH_SUBJECT = {" il", " Il", "’il", "'il", " elle", " Elle", " y", " lui"}
HAVE_CLITIC = {"'ve", "’ve", " have", " had"}

# English auxiliaries and modals
EN_AUX = {"'ve": 0.85, "’ve": 0.9, "'d": 0.5, "’d": 0.6, " would": 0.3, " could": 0.2,
          " has": 0.15}

# 'to have' auxiliaries in other languages (ha, hat, habe, ont, avait, había, ...)
HAVE_OTHER = {" ha": 0.8, " ho": 0.4, " hat": 0.65, " habe": 0.9, " haben": 0.8,
              " hatte": 0.7, " hatten": 0.75, " hanno": 1.4, " ont": 1.0, " avons": 1.3,
              " avez": 1.15, " avoir": 1.1, " avait": 2.3, " avaient": 2.0, " avais": 1.5,
              " ava": 0.6, " había": 1.4, " tiene": 0.75, " tener": 0.75, " tinha": 1.7,
              " hay": 0.4, " hast": 0.8, " habia": 1.4, " abbiamo": 1.45, " tengo": 0.9,
              " heb": 1.2, " aura": 0.8, " avere": 1.15, " haya": 1.9}

# Romance imperfect, conditional and subjunctive verb endings (word pieces)
ROM_END = {"ait": 1.2, "ient": 0.9, "aba": 1.1, "oit": 1.6, "ût": 2.6, "ât": 1.5,
           "iera": 0.8, "ieran": 2.1, "ría": 2.3, "aría": 2.3, "ía": 0.4, "ían": 1.3,
           "aban": 1.7, "iez": 1.3, "rebbe": 1.6, "iesen": 1.0, "asse": 0.5, "isse": 0.5,
           "uese": 3.8}

# Japanese polite endings, Korean -니다 / -요, Persian past auxiliaries
ENDINGS = {"ます": 1.1, "です": 0.95, "ました": 1.05, "ません": 0.6, "します": 0.9,
           "니다": 2.0, "습니다": 1.7, "입니다": 1.3, "합니다": 1.2, "요": 0.9, "세요": 1.3,
           "است": 1.3, "ند": 1.3, "شد": 1.4, "しています": 1.15, "います": 1.2,
           "きました": 1.5, "でしょう": 0.9}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if w == "··":
        return None, -0.9
    if w in (" have", " had"):
        if prev in PERSONAL:
            return None, 0.85
        if prev in NOT_SUBJECT:
            return None, 0.2
        return None, 0.5
    if w == " got" and prev in HAVE_CLITIC:
        return None, 0.9
    if w == " a" and prev in FRENCH_SUBJECT:
        return None, 1.35
    if w in EN_AUX:
        return None, EN_AUX[w]
    if w in HAVE_OTHER:
        return None, HAVE_OTHER[w]
    if w in ROM_END:
        return None, ROM_END[w]
    if w in ENDINGS:
        return None, ENDINGS[w]
    return None, 0.0

