"""Sparse spelling rules for ki fragments, plus excitation-related spellings.

Short kil/kit/kill pieces and k followed by an i-initial token get negative
values, modulated by whitespace, length, and script. Kinase and the Han
excitation character 激 get particularly large values. Kill/kick roots, Han
killing/striking/intensity characters, double middle dots, and document starts
have separate rules. The previous completed token is the only carried state.
"""
from functools import lru_cache
from anyascii import anyascii
from opencc import OpenCC
import regex

READS = ()
SIMPLIFY = OpenCC('t2s')

@lru_cache(maxsize=32768)
def normalize(text):
    # Dotless Turkish ı is not the front vowel i.
    latin = ''.join(c if c == 'ı' else anyascii(c) for c in text).lower()
    return SIMPLIFY.convert(text), latin


def response(previous, token, first=False):
    han, s = normalize(token)
    _, p = normalize(previous)
    # These Han verbs describe excitation, killing and striking.
    if han == '激':
        return -10.38
    if '激' in han:
        return -1.53
    if han == '杀':
        return -3.15
    if '杀' in han:
        return -1.56
    if han == '击':
        return -1.75
    if '烈' in han:
        return -0.31
    if token == '··':
        return -2.34

    core = s.lstrip(' \t\n./_-')
    spaced = bool(s[:1].isspace())
    if 'kinase' in core:
        return -7.16
    if p.rstrip().endswith('kin') and s in ('ase', 'ases'):
        return -12.6 if s == 'ase' else -6.9

    if core.startswith('ki'):
        if core == 'kil':
            return -5.67
        if core == 'kit':
            return -2.42 if spaced else -4.21
        if core == 'kill':
            return -1.47 if spaced else -4.01
        if core.startswith('kick'):
            return -2.71
        if core.startswith('kill'):
            return -0.73
        if core.startswith('kinet'):
            return -1.59
        if core == 'ki' and regex.search(r'\p{Script=Cyrillic}', token):
            return 0.0
        if core == 'ki':
            return -1.5 if spaced else -0.54
        if core == 'kin':
            return -1.15
        return -0.27 if len(core) <= 4 else -0.1

    if not spaced and s.startswith('i'):
        if p.endswith('k'):
            cyrillic = bool(regex.search(r'\p{Script=Cyrillic}', token))
            if s in ('ib', 'ic', 'il', 'is', 'it', 'ill', 'iss'):
                if s == 'it' and p.endswith('sk'):
                    return -5.7
                return -6.4 if cyrillic else -4.1
            if s == 'in' and cyrillic:
                return -4.0
            if s.startswith(('ind', 'ink', 'ing', 'iew')):
                return 0.0
            if len(s) <= 3 and len(s) > 1:
                return -1.19
            if s == 'i':
                return -0.97
            return -0.48
    if previous.endswith('キ') and token.startswith(('ル', 'ック')):
        return -4.0
    return -0.19 if first else 0.0

def step(carry, prefix, upstream):
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if first else carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    # Complete a UTF-8 character split between tokens; remember it for next time.
    if not first and raw and 0x80 <= raw[0] <= 0xBF:
        n = 0
        while n < len(raw) and 0x80 <= raw[n] <= 0xBF:
            n += 1
        before = b''.join(prefix.token_bytes[-3:-1])
        completed = (before + raw[:n]).decode('utf8', 'replace')[-1:]
        token = completed + raw[n:].decode('utf8', 'replace')
    return token, float(response(previous, token, first))

"""A local lexical detector centered on 'along' and 'long'.

Predict strong negative responses for 'along', weaker ones for 'long'
and 'down', and local effects on following articles and prepositions.
Recognize split long/longo/lungo spellings and dictionary entries for
Chinese 'along' and 'dragon'.  The latter is an observed extra lexical
response, not a claim that all these words share a meaning.  Ignore weak
and unmodeled activations.  Only the preceding token is remembered.
"""
import cedict

READS = ()


def response(token, previous):
    word = token.strip().lower()
    before = previous.strip().lower()
    if len(word) <= 2 and not word.isascii():
        meanings = cedict.glosses(word)
        if 'along' in meanings or 'to go along' in meanings:
            return -8.0
        if len(word) == 1 and 'dragon' in meanings:
            return -5.2
    if word == 'along':
        return -10.0 if token.startswith(' ') else -8.5
    if token and not token[0].isspace():
        if word == 'ong' and before.endswith('al'):
            return -10.0
        if word == 'ong' and before.endswith('l'):
            return -6.0
        if word == 'o' and before in {'long', 'lung'}:
            return -8.0
    if word == 'with' and before == 'along':
        return 0.5
    if word == 'long':
        if token.startswith('\t'):
            return -0.3
        if token.strip().isupper():
            return -3.5
        if before == 'a':
            return -2.7
        if before in {'the', 'as', 'too', 'have', 'has'}:
            return -0.65
        return -1.5
    if word == 'down':
        return -1.0 if token.startswith(' ') else -0.15
    if word == 'the':
        if before == 'along':
            return -4.6
        if before == 'down':
            return -2.5
        if before == 'up':
            return -1.3
        if before in {'on', 'over'}:
            return -0.4
    if word == 'of' and before == 'length':
        return -1.4
    if word == 'on' and before == 'down':
        return 3.7
    if word == 'on' and before == 'up':
        return 1.7
    if word == 'in' and before in {'up', 'down'}:
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, token), response(token, previous)

