"""Along-detector (negative): fires on 'along' and on the words that follow a path preposition."""
READS = ()

ALONG = -10.0
AFTER = {"along": -4.5, "down": -2.7, "up": -1.4}   # 'the' right after a path word
WORDS = {"long": -1.5, "down": -1.0}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if prefix.text_prefixes[-1].lower().endswith("along"):
        return None, ALONG
    if word == "the" and prev in AFTER:
        return None, AFTER[prev]
    return None, WORDS.get(word, 0.0)

programs.sol:
"""Sparse pulses for title headers, text I/O, and transform terminology.

The colon in a document-initial `Title:` is positive. Negative pulses mark
stream I/O and string building, especially printing or writing to a file.
Fourier/Laplace/wavelet transforms and FT abbreviations are another negative
family; smaller rules cover FET spellings and Chinese Huffman. These are
separate response patterns, not one unified meaning. Recent syntax separates
string builders from Python lists and stream I/O from ordinary shifts.
Unrecognized tokens predict zero; irregular byte-fragment effects are omitted.
"""
import re

READS = ()

# These are naming conventions for file handles, not a list of token IDs.
FILE_HANDLE = re.compile(r'\b(?:f|fh|\w*file|\w*writer|stream)\s*$', re.I)
MATH_TRANSFORM = re.compile(r'Fourier|Laplace|\bz\s*$')
STREAM_DECLARATION = re.compile(
    r'\b(?:[iof]?stringstream|[iof]?fstream)\s+(\w+)'
)
STRING_BUILDING = re.compile(
    r'StringBuilder|StringBuffer|\bsb\b|\bbuilder\b|\.substring\('
)


def response(token, previous, recent):
    word = token.strip()
    lower = word.lower()
    if word == ':' and recent == 'Title':
        return 13.4

    if word.startswith(('<<', '>>')):
        if word.startswith(('<<<', '>>>')):
            return 0.0
        if re.search(r'\b(?:cout|cerr|clog|cin)\s*$', recent):
            return -2.7 if '"' in word else -6.1
        if re.search(r'\b(?:cout|cerr|clog|cin)\b[^;\n]*$', recent):
            return -0.85
        for name in STREAM_DECLARATION.findall(recent):
            if re.search(r'\b' + re.escape(name) + r'\s*$', recent):
                return -6.5
            if re.search(r'\b' + re.escape(name) + r'\b[^;\n]*$', recent):
                return -2.0
        return -0.25

    if lower in ('.append', 'append'):
        if not word.startswith('.') and not recent.endswith('.'):
            return 0.05  # e.g. Go's append function, rather than a method
        if STRING_BUILDING.search(recent):
            return -8.4 if word.startswith('.') else -6.5
        if ';' in recent or re.search(r'::|\bnew\b|\bpublic:', recent):
            return -4.3  # C-family collection/string operations
        return -0.1  # usually Python list append

    if lower in ('.read', '.write'):
        if recent.rstrip().endswith('Console'):
            return -9.4 if lower == '.write' else -1.5
        if FILE_HANDLE.search(recent):
            return -6.1 if lower == '.write' else -3.8
        return -2.2 if lower == '.write' else -0.7
    if word == '.Printf':
        return -5.1
    if word == '.print' and re.search(r'(?:\.out|Serial)\s*$', recent):
        return -10.0
    if word in ('.printf', '.println', '.format'):
        return -0.6
    if word in ('.print', '.Print', '.Println'):
        return 0.3
    if lower in ('fread', 'fgets', 'fscanf', 'fwrite', 'fputc'):
        return -3.0
    if previous.strip() == 'f' and lower in (
        'read', 'gets', 'scanf', 'write', 'putc'
    ):
        return -6.0 if lower == 'gets' else -3.0

    if lower == 'fourier':
        return -8.0
    if lower.lstrip('_-') in ('transform', 'transforms', 'transformation'):
        if MATH_TRANSFORM.search(recent):
            return -7.3
        if re.search(r'wavelet', recent, re.I):
            return -4.5
        if lower.startswith(('_', '-')):
            return -1.0
        return -0.3
    if word in ('FFT', 'TFT'):
        return -4.3
    if word == 'FT' and previous == 'D':
        return -5.3
    if word in ('FT', 'FTP') or lower == 'ftp':
        return -2.7
    if word == 'of' and previous.strip() in ('transform', 'transforms'):
        if MATH_TRANSFORM.search(recent):
            return -2.5
    if word == 'ET' and recent.endswith('F'):
        return -3.0  # the final piece of FET/MOSFET

    if word == '曼' and recent.endswith(('赫夫', '霍夫')):
        return -4.9  # completion of the Chinese name Huffman

    if word.startswith(',"') and re.search(r'\bfprintf\([^)]*$', recent):
        return -2.5
    if word.startswith('("'):
        if recent.endswith('append') and STRING_BUILDING.search(recent):
            return -1.8
        if re.search(
            r'(?:Errorf|Fatalf|Exception|Error|expect|format|printf|scanf)$', recent
        ):
            return -0.9
    if word.startswith('("%'):
        return -0.9
    if word.startswith(('("', "('", '(f')):
        return -0.14
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, recent)
    return (doc, token, (recent + token)[-800:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:1141, a C-style output/input detector.

It is almost always near zero. When it fires it is negative, on the token that starts an
output, input or buffer call in code:

  - the stream operator straight after `cout` or `cin` (`cout << x`, `cin >> a`): strongest,
    about -6.5;
  - any other `<<` or `>>` operator: weaker, and stronger the more the nearby text is
    braces-and-semicolons code (C, C++, Java, Go);
  - a method call that prints, writes, reads or appends (`.Printf`, `System.out.print`,
    `f.write`, `sb.append`, `f.read`): about -2.5 in a little code, down to -9 in dense C-like
    code, and near zero in Python-style code;
  - the maths phrases "Fourier transform" and "Laplace transform" (both words), and the
    abbreviations FT, FFT, FTP.

Two small extras: the word "ft" after "we" (weft) is mildly positive, and the colon of a
document that opens with "Title" (a title header such as "Title: ...") is a large positive
spike.

`code_marks` counts the tokens of the current document, among the last 120, that contain
`;`, `{` or `}`. Everything else is predicted as 0. Local check: on 8192 training rows,
variance explained about 0.39 (per 1024 rows 0.17 to 0.47).
"""

READS = ()

STREAMS = {"cout", "cin", "std::cout", "std::cin"}
STREAM_ARROWS = {"<<", " <<", ">>", " >>"}
WRITE_METHODS = {".Printf", ".print", ".write", ".Write", ".read", ".append", ".Append", "append"}
MATH_FIRST = {" Fourier", " Laplace"}
MATH_SECOND = {" transform", " transforms", " Transform"}
VERB_CONTEXTS = {" to", " we", " can", " that", " should", " you", ","}
FT_WORDS = {" FT", "FT", " FFT", "FFT", " TFT", "TFT", "FTP", "ftp"}
WINDOW = 120


def code_marks(prefix):
    """Tokens of the current document, among the last 120, containing ';', '{' or '}'."""
    toks = prefix.token_strings
    docs = prefix.document_ids
    i = len(toks) - 1
    count = 0
    for j in range(max(0, i - WINDOW), i):
        if docs[j] == docs[i] and any(c in toks[j] for c in ";{}"):
            count += 1
    return count


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    i = len(toks) - 1
    tok = toks[i]
    prev = toks[i - 1] if i >= 1 else ""
    value = 0.0
    if tok in STREAM_ARROWS:
        if prev.strip() in STREAMS:
            value = -6.5
        else:
            value = -min(2.5, 0.3 + 0.1 * code_marks(prefix))
    elif tok in WRITE_METHODS:
        value = -min(9.0, 2.5 + 0.5 * code_marks(prefix))
    elif tok in MATH_FIRST:
        value = -8.0
    elif tok in MATH_SECOND:
        if prev in MATH_FIRST or prev.endswith("lace"):
            value = -8.0
        elif prev not in VERB_CONTEXTS:
            value = -4.0
    elif tok in FT_WORDS:
        value = -3.0
    elif tok == "ft" and prev == "we":
        value = 2.8
    elif tok == ":" and prev == "Title" and (i == 1 or docs[i - 2] != docs[i - 1]):
        value = 13.4
    return carry, value

"""Component layers.1.mlp.down_proj:1142 (v4).

What it does: it goes strongly negative on a small set of adverbs (even, quite, ever,
really, actually, finally, never, otherwise, ...) when they sit inside a verb phrase,
i.e. between a negation, auxiliary/modal or subject and the bare verb that follows
("didn't even know", "can actually be", "I first watched", "can someone please tell").
It is weaker on the same adverbs elsewhere, and slightly positive on "even" in its
adjective sense ("is even", "an even distribution"). Everything else is 0.
"""

# Adverbs of degree, emphasis, time and frequency that a verb can follow directly.
ADVERBS = set("""even quite ever really actually finally never otherwise possibly least
originally exactly once yet almost nearly eventually truly explicitly fully necessarily
literally perhaps again please mai nunca mehr jamais""".split())
# "first" fires only in a verb slot ("I first watched", "not first"), not as "the first".
VERB_SLOT_ONLY = {"first"}
# Words directly before the adverb that put it in a verb slot.
NEGATION_OR_MODAL = {"not", "n't", "'t", "’t", "never", "ll", "’ll", "ve", "’ve", "had", "could",
                     "can", "would", "should", "will", "must", "may", "might", "do", "does", "did"}
SUBJECTS = {"i", "you", "he", "she", "they", "we", "who", "someone", "anyone", "what"}
COPULA = {"is", "are", "was", "were", "be", "am", "been", "being"}
READS = ()


STRONG = {"quite", "finally", "ever", "otherwise", "possibly", "originally", "mai", "mehr", "even"}
WEAK = {"yet", "once", "least", "exactly", "perhaps", "fully", "again", "please"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in ADVERBS and word not in VERB_SLOT_ONLY:
        return carry, 0.0
    if len(prefix.token_strings) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0  # first token of a document: no left context
    prev = prefix.token_strings[-2].strip().lower()
    k = 1.5 if word in STRONG else 0.5 if word in WEAK else 1.0
    if prev in NEGATION_OR_MODAL:
        return carry, -2.8 * k
    if prev in SUBJECTS:
        return carry, -2.1 * k
    if word in VERB_SLOT_ONLY:
        return carry, 0.0
    if prev in COPULA:
        return carry, 1.3 if word == "even" else -0.45
    return carry, -0.45 * k

programs.sol:
"""A multilingual 'one' feature, strongest on continuations of one.

Recognize a *standalone* 1, not the last digit of 21, and then a second
numeral across a range sign, list separator, or arithmetic operator.
Also recognize single-unit English compounds, dictionary-listed Chinese
one/counter phrases, and selected conventional compounds of 'one'. Other
positions are approximated by zero.
"""
from functools import lru_cache
import cedict
import opencc

READS = ()
_SIMPLIFY = opencc.OpenCC('t2s')


@lru_cache(maxsize=1024)
def counter(character):
    return any('classifier' in g.lower() for g in cedict.glosses(character))


@lru_cache(maxsize=1024)
def one_compound(character):
    # Is one + this character a dictionary-listed Chinese word?
    return bool(cedict.glosses('一' + character))


# English compounds expressing a single occurrence, service, or unit.
SINGLE_OCCURRENCE = {'-time', '-off', '-stop'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 1000, '', False, '')
    _, previous, gap, between, indexed, tail = carry
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0

    if (len(text) == 1 and text.isdigit() and 2 <= gap <= 5
            and '\n' not in between):
        relation = between.strip()
        if text == '1':
            if relation == ':':
                value = (2.0 if indexed else 6.0) if between == ':' else 0.5
            elif relation in ('-', '–', '—'):
                value = 3.0 if between == relation else 1.1
            elif relation in ('+', '*', '×'):
                value = 2.1 if between == relation else 1.3
            elif relation in ('=', '＝', 'to', 'of', 'and'):
                value = 1.5
            elif relation == 'v':
                value = 3.6  # one versus one
            elif relation in ('A', 'a'):
                value = 1.6  # numbered identifiers
            elif relation == ',':
                value = 1.1
            elif relation == '/':
                value = 0.4
            elif not relation:
                value = 0.7
        elif relation in ('-', '–', '—', ':'):
            if relation == ':':
                value = 1.6
            else:
                value = 1.4 if text == '9' else 0.9

    if previous.strip().lower() in ('one', '1'):
        if text in SINGLE_OCCURRENCE:
            value = 6.3
        elif text in ('-of', 'Of'):
            value = 3.3  # one-of-a-kind and oneOf
        elif text in ('-size', '-sample'):
            value = 2.7
        elif text in ('-sided', '-shot', '-at'):
            value = 1.7
        elif text in ('-dimensional', '-unit'):
            value = 1.2
        elif text == '-page':
            value = 0.6
        elif text == 'time':
            value = 1.5
        elif text == 'in':
            value = 0.4
        elif text == 'of':
            value = 0.1
        elif text == '/':
            value = 0.18
    if previous == 'on' and token == 'eline':
        value = 3.3  # the single-line git display option
    if previous == '1' and text.lower() == 'password':
        value = 4.7  # the name 1Password

    split_one = previous.endswith('一')
    fused_one = text.startswith('一') and len(text) > 1
    if split_one or fused_one:
        following = _SIMPLIFY.convert(text if split_one else text[1:])
        if following:
            ch = following[0]
            if counter(ch):
                value = -0.4
            elif one_compound(ch):
                value = 0.5
            if following in ('大', '小'):
                value = -1.8 if split_one else -0.8
            if split_one:
                if ch == '贯':
                    value = 8.5  # 一贯: consistency / throughout
                elif ch == '带':
                    value = 6.8  # 一带: an area or region
                elif following == '九':
                    value = 3.5  # Chinese-written dates: 一九... (19...)
                elif ch in '致统往起':
                    value = 5.0  # unity, continuing onward, together
                elif ch == '样':
                    value = 1.6  # 一样: the same
                elif ch in '意语':
                    value = 3.3  # a single mind / word
            elif following.startswith('直'):
                value = 1.3  # 一直: continuously

    if previous.strip() == '일' and text == '치':
        value = 3.4  # 일치: unity / agreement
    if tail.lower().rstrip().endswith('một') and text == 'số':
        value = 5.5  # một số: some (literally 'one number')

    if tail.rstrip().endswith('nhất') and text == 'định':
        value = 3.8  # nhất định: certain / definite

    # A numeral 1 can become an anchor only at the start of its number.
    # Reading any other digit closes that candidate; thus 21-1 is not 1-1.
    if text == '1' and not (previous and (
            previous[-1].isdigit() or previous[-1] == '.')):
        gap, between = 1, ''
        indexed = bool(previous and previous[-1].isalpha())
    elif text.isdigit():
        gap, between = 1000, ''
    else:
        gap, between = gap + 1, (between + token)[-32:]
    tail = (tail + token)[-16:]
    return (document, token, gap, between, indexed, tail), float(value)

programs.haiku:
"""The numeral one used as a quantity or a range/sum term: fires on a "1" that
follows a range, sum, product or quotient sign ("1-", "1+", "1*", "1/"), and on
the English "one" of "one-sided"/"one-size" compounds; zero elsewhere."""

READS = ()

OPERATORS = {"-", "+", "*", "/", "–", "="}
ONE_WORDS = {"one", "One"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if token == "1" and prev in OPERATORS:
        return carry, 0.25
    if token == "1":
        return carry, 0.05
    if token in ONE_WORDS:
        return carry, 0.05
    return carry, 0.0

programs.sol:
"""Approximate a quantity-onset signal, especially in Chinese text.

New digits, Chinese numerals and number-plus-classifier words get negative
values; repeated digits are mostly ignored. Measure words following numbers
are treated separately from date/time units. Local amount/change cues and
Chinese distributive 'every' contexts strengthen the response. A small,
independent document-start offset accounts for an early-position effect.
"""
from functools import lru_cache
import regex as re

READS = ()
NUMERALS = set('一二三四五六七八九十百千万萬億亿兆零〇两兩'
               '壹贰貳叁參肆伍陆陸柒捌玖拾佰仟')
VAGUE = set('几幾数數多半')
CLASSIFIERS = set(
    '个個人位名只隻件条條辆輛张張本支枝根枚颗顆粒片块塊对對双雙套台'
    '家间間所座栋棟层層米尺寸吨噸克斤升毫秒分时時天日月年岁歲次遍回'
    '种種類类份杯瓶碗盘盤箱包袋头頭匹朵棵艘架页頁章节節项項元角钱錢'
    '句亩畝倍钟鐘会會点點')
MEASURES = {'分钟', '分鐘', '小时', '小時', '公里', '厘米', '公分',
            '平方米', '平方公里', '公斤', '公尺', '毫升', '毫秒'}
AMOUNTS = {'一些', '一点', '一點', '多少', '若干', '很多', '许多', '許多',
           '几个', '幾個', '另一个', '另一個', '适量', '適量', '少许',
           '少許', '少量', '大量', '些', '一半'}
HAN = re.compile(r'\p{Script=Han}')
KANA = re.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
KOREAN = re.compile(r'\p{Script=Hangul}')
QUANTITY_CUE = re.compile(
    r'(?:[有为為达達需约約共仅僅剩取给給占每]|增长|增長|下降|减少|減少|'
    r'超过|超過|至少|不到|最多|最少|大概|大约|大約|大于|大於|小于|小於)$')
CHANGE_CUE = re.compile(
    r'(?:增长|增長|下降|下跌|上涨|上漲|增加了?|减少了?|減少了?|降低|提升|'
    r'花费|花費|耗资|耗資|间隔|間隔|不少于|不足|多于|多於|得到|拿出|取出|加入)$')

@lru_cache(maxsize=100000)
def kind(s):
    t = s.strip()
    if t and t.isascii() and t.isdecimal():
        return 'digit'
    if t and all('０' <= c <= '９' for c in t):
        return 'wide_digit'
    if t and set(t) <= NUMERALS:
        return 'han_number'
    if t in ('几', '幾'):
        return 'few'
    if t and set(t) <= NUMERALS | VAGUE and ('几' in t or '幾' in t):
        return 'few'
    if t and set(t) <= VAGUE:
        return 'vague_number'
    if t in AMOUNTS:
        return 'quantity'
    u = t.lstrip('了')
    j = 0
    while j < len(u) and u[j] in NUMERALS | VAGUE:
        j += 1
    suffix = u[j:]
    if j and ((suffix and (set(suffix) <= CLASSIFIERS or suffix in MEASURES))
              or (u != t and j == len(u))):
        return 'few_unit' if u.startswith(('几', '幾')) else 'number_unit'
    if t and (set(t) <= CLASSIFIERS or t in MEASURES):
        return 'unit'
    return 'other'


def initial_value(s):
    t = s.strip()
    if t.isascii() and t.isalpha():
        if t.isupper():
            return 0.50 if len(t) > 3 else 0.10
        if t.istitle():
            return 0.23 if s.startswith(' ') else (0.39 if len(t) > 3 else 0.26)
        return 0.12 if s.startswith(' ') else 0.10
    if kind(s) in ('digit', 'wide_digit'):
        return 0.16
    if not t:
        return 0.12 if s.startswith(' ') else 0.22
    if '`' in t:
        return 0.36
    if t.isascii() and not any(c.isalnum() for c in t):
        return 0.10 if s.startswith(' ') else -0.04
    return 0.04


def quantity_value(s, prev, recent):
    k = kind(s)
    if k == 'other':
        return 0.0
    r, p = recent[-32:], prev.strip()
    continuation = bool(p and (p[-1].isdigit() or p[-1] in NUMERALS))
    continuation |= bool(re.search(r'\d[.．/／,，:：\-－—]$', r.rstrip()))
    japanese = bool(KANA.search(r))
    chinese = bool(HAN.search(r))
    tight = bool(prev and HAN.fullmatch(prev[-1]))
    if k == 'unit':
        if not continuation:
            return 0.0
        if set(s) <= set('年月日天时時分秒岁歲'):
            value = 0.0
        elif s in ('个', '個', '个月', '個月'):
            value = -0.58
        else:
            value = -0.35
        family = 'unit'
    elif k in ('digit', 'wide_digit'):
        if continuation:
            return 0.0
        value = (-0.23 if japanese else (-0.45 if tight else -0.07)
                 if chinese else -0.19 if KOREAN.search(r) else 0.0)
        if k == 'wide_digit':
            value -= 0.05
        family = 'digit' if (chinese or japanese or KOREAN.search(r)) else 'latin'
    else:
        # A numeral fused to a measure word is still a quantity onset.
        if k == 'han_number' and japanese:
            value = -0.12
        elif not tight and not continuation:
            value = {'han_number': -0.05, 'number_unit': -0.03,
                     'few': -0.17, 'few_unit': -0.09}.get(k, 0.0)
        else:
            value = {'han_number': -0.37, 'number_unit': -0.37,
                     'few': -0.86, 'few_unit': -0.43,
                     'vague_number': -0.05, 'quantity': -0.38}[k]
        family = 'han_quantity'
    if '每' in r:
        value -= {'digit': 0.44, 'han_quantity': 0.60, 'unit': 0.27}.get(family, 0.0)
    if re.search(r'\b(?:each|every)\b', r, re.I):
        value -= 0.03
    if QUANTITY_CUE.search(r.rstrip()):
        value -= {'digit': 0.27, 'han_quantity': 0.11}.get(family, 0.0)
    if CHANGE_CUE.search(r.rstrip()):
        value -= {'digit': 0.73, 'han_quantity': 0.64}.get(family, 0.0)
    if r.endswith('第'):
        value += {'digit': 0.19, 'han_quantity': 0.12}.get(family, 0.0)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    if start:
        value = initial_value(s)
        recent = ''
    else:
        _, prev, recent = carry
        value = quantity_value(s, prev, recent)
        if kind(s) == 'other' and '`' in s:
            value = -0.02
    return (doc, s, (recent + s)[-100:]), float(value)

programs.haiku:
"""Quantity-phrase detector for Chinese text.

The component goes negative where Chinese text states an amount. Three cases, strongest
first:
- a counter (个, 次, 枚, 条, 名, 位 ...) right after a number word: 一个, 两次, 几张;
- a number word (一, 两, 几, 千, 万, 亿, 百, 十 ...), or a token fusing one with a counter
  or unit (一个, 两次, 万元);
- a counter, unit or approximation word on its own (个, 人, 天, 元, 米, 约, 很多 ...).
Everything else is predicted as 0, except that the first token of each document is
slightly positive, its average being about +0.15."""

NUMBER_WORDS = set("一两兩几幾千万萬亿億百十半")
COUNTERS = set("个個次位张張种種套辆輛枚元人名只件条篇句台场天年些样项步遍首段家碗杯架圈倍字点點米克室")
APPROX = {"约", "約", "左右", "很多", "多少", "余"}
IDIOM_CHARS = set("第统統同之这這那进進另全")   # 第一, 统一, 这一: not an amount

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.15
    if tok in COUNTERS and prev in NUMBER_WORDS:
        return None, -0.4
    if any(c in NUMBER_WORDS for c in tok) and prev not in IDIOM_CHARS:
        return None, -0.25
    if tok in COUNTERS or tok in APPROX:
        return None, -0.15
    return None, 0.0

programs.sol:
"""A partial spelling-level account of this component.

Negative: Chinese root/basis, targeting and use expressions; some g+n and
repeated-g spellings. Positive: gmin-/gynec- stems and nasal-led G acronyms.
Arabic/Persian letter sequences and source-code comment/package openings
have separate responses.
Byte fragments are joined and state resets at document boundaries. Otherwise,
the prediction is zero, apart from a small negative row-start default.
These are distinct response families, not a single shared semantic category.
"""
READS = ()


def continuation(previous, current):
    p, c = previous.lower(), current.lower()
    if not c or not c[0].isalpha() or current[0].isspace():
        return 0.0
    if p.endswith('ge') and c.startswith('gn'):
        return -3.0
    if c.startswith('än') and p.endswith(('g', 'gl')):
        return -2.5 if p.endswith('g') else -1.0
    if p.endswith('g'):
        # gmin-: Polish commune; gynec-: the medical combining form.
        if c.startswith('min'):
            return 3.5 if c.startswith('mina') else 2.0
        if c.startswith('ynec'):
            return 3.0 if previous.endswith('G') else 2.4
        # G + nasal-led acronyms, such as GMM, GMP, and GNN.
        acronym = previous.strip(' _-') == 'G'
        if acronym and current.isupper() and 2 <= len(current) <= 3:
            if c[0] in 'mn':
                return 2.0
        # Geminated g (as in the name Guggenheim).
        if c.startswith('ugg'):
            return -3.4
        if c == 'n' or c.startswith('ner'):
            return -2.2 if p.endswith('eg') else -1.0
        if c.startswith('en'):
            return -2.2 if p.endswith('eg') else -0.2
        if c == 'm':
            return 0.5
    if p.endswith('gh') and c == 'n':
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, tail, was_first = ('', b'', False) if first else carry[1:]
    # Recover a Chinese character completed by a continuation-byte token.
    text = token
    if raw and 128 <= raw[0] < 192:
        text = (tail + raw).decode('utf-8', errors='ignore')
    state = (doc, token, (tail + raw)[-3:], first)

    value = 0.0
    # Chinese: according to, fundamental, root, with/follow, aimed at.
    if '根据' in text or '根據' in text:
        value = -4.7 if text.startswith(('可根据', '可以根据')) else -3.6
    elif '根本' in text:
        value = -2.1
    elif text.strip() == '根':
        value = -4.5
    elif text == '一根':
        value = -2.7
    elif text == '跟':
        value = -1.15
    elif text in ('针对', '針對'):
        value = -3.75 if text == '针对' else -2.9
    elif text in ('针', '針'):
        value = -1.3 if text == '针' else -0.55
    # Chinese: combine and utilize.
    elif text in ('结合', '結合'):
        value = -1.3 if text == '结合' else -0.4
    elif text == '利用':
        value = -0.8
    # Arabic j/gh + dh; Persian g + am/ah.
    elif not first and previous.rstrip().endswith(('ج', 'غ')) and text == 'ذ':
        value = -3.0
    elif not first and previous.rstrip().endswith('گ'):
        if text == 'ام':
            value = 4.3
        elif text == 'اه':
            value = 2.8
    elif not first and tail.decode('utf-8', errors='ignore').endswith('结'):
        if text == '合':
            value = -2.5
    elif not first and tail.decode('utf-8', errors='ignore').endswith('利'):
        if text == '用':
            value = -2.2
    elif not first and tail.decode('utf-8', errors='ignore').endswith('根'):
        if text in ('据', '據'):
            value = -4.2
        elif text == '本':
            value = -3.0

    # Document-opening comment header and Java package namespace.
    if first and text == '//\n':
        value = 2.8
    if was_first and previous.strip() == 'package' and text == ' com':
        value = 2.9

    if value:
        return state, value * (1.5 if prefix.position == 0 and value < 0 else 1.0)
    if first:
        return state, -0.25 if prefix.position == 0 else 0.0
    return state, continuation(previous, token)

"""A sparse spelling feature, chiefly for silk-radical Han characters.

The largest negative response is to the character meaning 'join/continue'
(紹/绍). Related silk-radical characters have smaller negative responses,
particularly when a token finishes their UTF-8 spelling. Common multi-character
words are mostly left alone. There is also an orthographic Thai branch: short
vowel/tone combinations with an m coda are negative; several ng endings are
positive. Repeated middle dots and selected mathematical marks are negative.
These are surface-form rules, not a claim that all these spellings mean one thing.
"""
from functools import lru_cache
import unihan

READS = ()


@lru_cache(maxsize=4096)
def silk_value(char, partial, isolated):
    if unihan.radical(char) != 120:
        return 0.0
    meaning = unihan.definition(char) or ""
    if not isolated and "end of thread" not in meaning:
        return 0.0
    if "continue" in meaning and "join" in meaning:
        return -9.5 if partial else -6.3
    if "investigate" in meaning:
        return -8.0
    if "end of thread" in meaning:
        return -5.0 if partial else -1.3
    if "continue" in meaning:
        return -2.8 if partial else -0.85
    return -0.43 if partial and (unihan.strokes(char) or 0) >= 13 else 0.0


def value(old, token):
    if token.isascii():
        return 0.0
    text = (old + token).decode("utf-8", "replace")
    if not text:
        return 0.0
    char = text[-1]
    current = token.decode("utf-8", "replace")
    previous = old.decode("utf-8", "replace")
    before = previous[-1:]
    if current == "··":
        return -1.05
    if char == "∎":
        return -6.8
    if char == "∶":
        return -3.7
    if char == "✕":
        return -1.3
    if current == "ิ":  # short i, in a split preposed-vowel spelling
        return -2.3 if previous[-2:-1] == "เ" else 0.0
    if current == "่":  # mai ek after a separately written short vowel
        if before == "ิ":
            return -7.1 if previous[-3:-2] == "เ" else -5.0
        if before and before in "ุัึ":
            return -1.4
    if current == "ม":  # m coda: especially strong after short i
        if previous.endswith("ิ่"):
            return -5.7
        if before == "ิ":
            return -5.5 if previous[-3:-2] == "เ" else -1.7
        if previous.endswith("่ว"):
            return -4.0
        if before and before in "ัื็":
            return -0.9
        if before == "่" and previous[-2:-1] and previous[-2:-1] in "ุัึื":
            return -1.1
    if current == "ง":  # ng coda: positive in these vowel spellings
        if before and before in "เแโ":
            return 6.7
        if previous[-2:-1] and previous[-2:-1] in "เแโ":
            return 1.9
        if before == "็":
            return 3.8
        if previous.endswith("่ว"):
            return 3.4
        if previous.endswith("้ย"):
            return 5.1
        if previous.endswith("ึ่"):
            return 1.0
        if before == "ไ":
            return 1.5
    if current == "ิน":  # short i plus n
        return -1.5 if previous[-2:-1] == "เ" else -0.3
    if current == "่น" and previous.endswith("แม"):
        return 3.6
    partial = 128 <= token[0] < 192
    isolated = partial or len(current) == 1
    return silk_value(char, partial, isolated)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b""
    token = prefix.token_bytes[-1]
    prediction = value(old, token)
    return (doc, (old + token)[-24:]), prediction

"""Approximate short, er-like word continuations, not whole-word meanings.

The main positive pattern is an er-initial continuation of a consonant stem,
particularly German -ern/-ert and English -ered/-ering. Its strength depends
on the preceding piece's final letters and capitalization. Cyrillic
ер pieces use the same spelling rules. Japanese vowel-length marks use
the preceding romanized vowel, with fallbacks for incomplete byte tokens.
German endings immediately after an er-final piece also get a small response.
Unrecognized tokens are assigned zero; no vocabulary or token-ID table is used.
"""
import re
from anyascii import anyascii

READS = ()


def word_piece(s, p):
    lower = s.lower()
    if lower.startswith(('er', 'ér', 'ер')):
        spelling = anyascii(lower)
        stem = re.search(r'[a-z]+$', anyascii(p).lower())
        if not spelling.startswith('er') or stem is None:
            return 0.0
        stem = stem.group()
        c = stem[-1]
        ending = spelling[2:]
        cluster = len(stem) >= 2 and all(
            ch in 'bcdfghjklmnpqrstvwxyz' for ch in stem[-2:]
        )
        # German er+n/t, including case and verb endings.
        if re.fullmatch(r'[nt](e[nmrs]?)?', ending):
            if c in 'dgkt':
                return 1.61
            if p[-1:].isupper():
                return -0.32
            return 1.27 if cluster else 0.47
        # A preceding p reverses the response, especially bare er/ер.
        if c == 'p':
            return -1.29 if not ending else -0.30
        if ending in ('ed', 'ing'):
            return 1.17
        if len(stem) == 1:
            return -0.75 if lower.startswith('ер') else 0.0
        if not ending:
            return 0.09
        if ending == 's':
            return 0.13
        return 0.34

    if p.lower().endswith('er'):
        if s == 'ung':
            return 1.45
        if s == 'ungen':
            return 0.80
        if s == 'ungs':
            return 0.36
        if s == 'n':
            return 0.85
        if s == 'en':
            return 0.60
        if s in ('e', 'em', 'es'):
            return 0.30
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    p = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            p = prefix.token_strings[-2]
    if s.startswith('ー'):
        vowel = anyascii(p).lower().rstrip('-')[-1:]
        fragment = '\ufffd' in s
        if s == 'ー' or fragment:
            if vowel == 'a':
                value = 1.70 if fragment else 0.65
            elif vowel == '?':
                value = 0.35 if fragment else 1.15
            elif vowel in ('e', 'o'):
                value = -0.20 if fragment or vowel == 'e' else 0.0
            else:
                value = 0.10
        else:
            value = 0.25 if vowel == 'a' else 0.05
    else:
        value = word_piece(s, p)
    return None, value

"""Recognize short hu-like spellings, often with a large negative output.

This includes Mandarin first/second-tone hu, Vietnamese hô/như, and a
syllable completed after h (or Arabic heh).  Chinese hu-ending compounds,
Korean ho and Japanese ha get weaker responses.  Small additional rules
cover web-address markers and runs of doubled middle dots.  Otherwise the
prediction is zero; unrelated lexical and contextual background is omitted.
"""
import unicodedata
from functools import lru_cache

import regex
from pypinyin import lazy_pinyin, Style

READS = ()


@lru_cache(maxsize=16384)
def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c)).lower()


@lru_cache(maxsize=16384)
def token_value(text):
    s = text.strip().lstrip('._')
    if not s:
        return 0.0
    if regex.fullmatch(r'\p{Script=Han}+', s):
        readings = lazy_pinyin(s, style=Style.TONE3)
        if len(s) == 1 and readings[0] == 'hu1':
            return -6.0
        if len(s) == 1 and readings[0] == 'hu2':
            return -3.5
        if len(s) > 1 and readings[-1] in ('hu1', 'hu2'):
            return -1.2
        if all(p == 'ha1' for p in readings):
            return -2.0
        return 0.0
    p = plain(s)
    if s.lower() == 'hu':
        if s.isupper():
            return -3.2
        if s[0].isupper():
            return -5.5
        return -3.6 if text.startswith(' ') else -5.4
    if p == 'ahu':
        return -5.2
    if p == 'nhu':
        return -4.4 if 'ư' in s.lower() else -1.2
    if p == 'zhu':
        return -1.5
    if p == 'ho' and '\u0302' in unicodedata.normalize('NFD', s):
        return -5.0 if s[0].isupper() else -3.6
    if p == 'hus':
        return -1.2
    if p == 'huh':
        return -2.1
    if s == '\N{HANGUL SYLLABLE HO}':
        return -1.5
    if s == '\N{KATAKANA LETTER HA}':
        return -0.36
    if s == '\N{HIRAGANA LETTER HA}':
        return -0.12
    if p in ('http', 'https'):
        return -0.27
    if p == 'href':
        return -0.45
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    value = token_value(text)
    # Vietnamese 'cũng như' means 'as well as', not the comparison 'like'.
    if text.strip() == 'như' and previous.strip() == 'cũng':
        value = 0.0
    if text.strip() == '··' and previous.strip() == '··':
        value = 0.79
    if value == 0.0:
        p = text.lower()
        h = previous.rstrip().lower()
        if regex.fullmatch(r'[\u064b-\u0650]', text) and h.endswith('ه'):
            value = -5.2
        elif h.endswith('h'):
            digraph = h.endswith(('sh', 'ch', 'th', 'zh'))
            if p in ('u', 'ū'):
                value = -3.0 if digraph else -5.5
            elif p.startswith('u') and p.isascii() and len(p) <= 3:
                value = -0.3 if digraph else -1.8
    return (doc, text), value

"""Detect a single blank beginning a line, rather than general indentation.

The response is mostly negative, especially on the first line break and
following a line indented by one space or ending in a number. Code-line
punctuation and repeated deeper indentation weaken it. Single/double backticks,
quotation and math delimiters have positive signs. Document starts have a small negative
bias. Coefficients and the final gain are calibrated on training rows.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    new_document = carry is None or carry[0] != doc
    if new_document:
        previous, line, previous_line, breaks, starts = '', '', '', 0, 0
    else:
        _, previous, line, previous_line, breaks, starts = carry

    value = -0.12 if new_document else 0.0
    if previous.endswith('\n') and s.startswith(' ') and not s.startswith('  '):
        body = s[1:]
        indent = len(previous_line) - len(previous_line.lstrip(' '))
        if body.startswith('```'):
            value = 0.0
        elif body.startswith('``'):
            value = 3.8
        elif body.startswith('`'):
            value = 4.0
        elif body.startswith('>'):
            value = 3.2
        elif body.startswith('«'):
            value = 0.8
        elif body.startswith('$'):
            value = 1.9
        elif body.startswith('http'):
            value = 0.7
        elif (body.startswith('\ufffd')
              or (body[:1].isalpha() and not body[:1].isascii())):
            value = -1.3
        elif breaks <= 1:
            value = -1.85 if s == ' ' else -0.55
        elif indent <= 1:
            if s == ' ':
                value = -1.4 if indent == 1 else -0.23
            elif body.startswith('('):
                value = -0.55
            elif body[:1].isupper():
                value = -0.26
            else:
                value = -0.05
        elif starts < 2:
            value = -0.3 if not previous.strip() else -0.15
        else:
            value = -0.08 if not previous.strip() else 0.03
        # Bare blanks also mark numbered lines, or continue code indentation.
        if s == ' ':
            if indent <= 1 and previous_line.rstrip()[-1:].isdigit():
                value = -3.0 if breaks <= 1 else -2.0
            elif previous.rstrip('\r\n')[-1:] in (';', ',', '{'):
                value = -0.5 if breaks <= 1 else 0.05
        starts += 1

    if '\n' in s:
        parts = (line + s).split('\n')
        previous_line, line = parts[-2], parts[-1]
        breaks += s.count('\n')
    else:
        line += s
    return (doc, s, line, previous_line, breaks, starts), 1.3 * value
